/* Penyelesaian penuh UKKM Set 5: Matematik & Sains (dimuat selepas kertas dihantar) */
(window.UKKM_SOL = window.UKKM_SOL || {})[5] = {"mat":["<h5>🧭 Faham soalan</h5><p>Jujukan bermula dengan 5, −10, 20 dan −40. Kita perlu mencari sebutan keenam, bukan sebutan seterusnya sahaja.</p><h5>💡 Strategi</h5><p>Cari operasi yang sama antara dua sebutan berturutan. Darab dengan −2 sesuai kerana nilai berganda dan tanda berselang-seli.</p><h5>✏️ Langkah penyelesaian</h5><ol><li>−10 ÷ 5 = −2; 20 ÷ (−10) = −2; −40 ÷ 20 = −2.</li><li>Sebutan kelima = −40 × (−2) = 80.</li><li>Sebutan keenam = 80 × (−2) = −160.</li><li>Jawapan: <b>B</b> (−160).</li></ol><h5>🔍 Semak jawapan</h5><p>Nilai mutlak sebutan keenam ialah 160 dan tandanya negatif, selaras dengan pola tanda positif, negatif, positif, negatif, positif, negatif.</p><h5>❌ Mengapa pilihan lain salah</h5><ul><li><b>A</b> (−320): diperoleh jika sebutan keenam, −160, didarab dengan 2 dan bukannya −2, iaitu terlebih satu langkah dengan tanda faktor yang salah.</li><li><b>C</b> (160): nilai mutlak betul tetapi tanda sebutan keenam sepatutnya negatif.</li><li><b>D</b> (320): nilai mutlak sebutan ketujuh, bukan keenam.</li></ul><h5>📌 Tip peperiksaan</h5><p>Nomborkan setiap sebutan sebelum meneruskan jujukan supaya tidak terlebih langkah.</p>",
"<h5>🧭 Faham soalan</h5><p>Ada 50 tiket dewasa dan kanak-kanak keseluruhannya. Harga masing-masing RM 12 dan RM 7, manakala kutipan ialah RM 455. Cari bilangan tiket kanak-kanak.</p><h5>💡 Strategi</h5><p>Gunakan dua hubungan: jumlah tiket dan jumlah wang. Nyatakan satu bilangan dengan pemboleh ubah supaya hanya satu persamaan perlu diselesaikan.</p><h5>✏️ Langkah penyelesaian</h5><ol><li>Ambil d sebagai bilangan tiket dewasa. Bilangan tiket kanak-kanak = 50 − d.</li><li>Kutipan: 12d + 7(50 − d) = 455. Kembangkan: 12d + 350 − 7d = 455.</li><li>5d = 455 − 350 = 105, maka d = 105 ÷ 5 = 21.</li><li>Tiket kanak-kanak = 50 − 21 = 29.</li><li>Jawapan: <b>C</b> (29).</li></ol><h5>🔍 Semak jawapan</h5><p>Semak kutipan: 21 × RM 12 + 29 × RM 7 = RM 252 + RM 203 = RM 455. Jumlah tiket juga 21 + 29 = 50.</p><h5>❌ Mengapa pilihan lain salah</h5><ul><li><b>A</b> (21): 21: ini bilangan tiket dewasa.</li><li><b>B</b> (25): 25: membahagi 50 sama rata tanpa menggunakan harga.</li><li><b>D</b> (35): 35: tidak memenuhi persamaan kutipan; 15 × 12 + 35 × 7 = RM 425.</li></ul><h5>📌 Tip peperiksaan</h5><p>Semak kedua-dua syarat asal selepas menyelesaikan masalah dua jenis tiket.</p>",
"<h5>🧭 Faham soalan</h5><p>Bilangan ahli berubah daripada 40 kepada 52. Soalan meminta peratus peningkatan berbanding bilangan asal, iaitu 40 orang.</p><h5>💡 Strategi</h5><p>Cari pertambahan dahulu, kemudian bahagi dengan nilai asal. Peratus perubahan sentiasa menggunakan keadaan awal sebagai asas.</p><h5>✏️ Langkah penyelesaian</h5><ol><li>Pertambahan ahli = 52 − 40 = 12 orang.</li><li>Nisbah pertambahan kepada bilangan asal = 12 ÷ 40 = 0.3.</li><li>Peratus peningkatan = 0.3 × 100% = 30%.</li><li>Jawapan: <b>D</b> (30%).</li></ol><h5>🔍 Semak jawapan</h5><p>Semak: 30% daripada 40 = 0.30 × 40 = 12; 40 + 12 = 52.</p><h5>❌ Mengapa pilihan lain salah</h5><ul><li><b>A</b> (1.3%): 1.3%: 52 ÷ 40 = 1.3 ialah faktor pertumbuhan, bukan peratus peningkatan.</li><li><b>B</b> (12%): 12%: 12 ialah bilangan ahli tambahan, bukan peratus.</li><li><b>C</b> (23.1%): 23.1%: 12 ÷ 52 × 100% ≈ 23.1%, menggunakan bilangan baharu sebagai asas.</li></ul><h5>📌 Tip peperiksaan</h5><p>Untuk peratus peningkatan, ingat rumus beza ÷ nilai asal × 100%.</p>",
"<h5>🧭 Faham soalan</h5><p>Nisbah wang Kamal kepada Lina ialah 5 : 3. Perbezaan penerimaan mereka ialah RM 48; yang ditanya ialah jumlah kedua-duanya.</p><h5>💡 Strategi</h5><p>Hubungkan beza bahagian nisbah dengan beza wang sebenar. Selepas memperoleh nilai satu bahagian, darab dengan jumlah bahagian.</p><h5>✏️ Langkah penyelesaian</h5><ol><li>Beza bahagian = 5 − 3 = 2 bahagian.</li><li>Dua bahagian = RM 48, jadi satu bahagian = RM 48 ÷ 2 = RM 24.</li><li>Jumlah bahagian = 5 + 3 = 8; jumlah wang = 8 × RM 24 = RM 192.</li><li>Jawapan: <b>B</b> (RM 192).</li></ol><h5>🔍 Semak jawapan</h5><p>Semak: Kamal = 5 × RM 24 = RM 120; Lina = 3 × RM 24 = RM 72; beza = RM 48 dan jumlah = RM 192.</p><h5>❌ Mengapa pilihan lain salah</h5><ul><li><b>A</b> (RM 384): RM 384: menganggap RM 48 sebagai satu bahagian lalu mendarab dengan 8.</li><li><b>C</b> (RM 120): RM 120: wang Kamal sahaja.</li><li><b>D</b> (RM 72): RM 72: wang Lina sahaja.</li></ul><h5>📌 Tip peperiksaan</h5><p>Tandakan beza bahagian dan jumlah bahagian secara berasingan dalam soalan nisbah.</p>",
"<h5>🧭 Faham soalan</h5><p>Jadual menunjukkan nilai 0 hingga 4 adik-beradik bersama kekerapan murid 3, 7, 6, 3 dan 1. Kita mencari min bagi semua murid.</p><h5>💡 Strategi</h5><p>Gunakan min berwajaran: darab setiap bilangan adik-beradik dengan kekerapan, jumlahkan, kemudian bahagi dengan jumlah murid.</p><h5>✏️ Langkah penyelesaian</h5><ol><li>Jumlah murid = 3 + 7 + 6 + 3 + 1 = 20.</li><li>Jumlah adik-beradik = (0 × 3) + (1 × 7) + (2 × 6) + (3 × 3) + (4 × 1) = 0 + 7 + 12 + 9 + 4 = 32.</li><li>Min = 32 ÷ 20 = 1.6 adik-beradik bagi seorang murid.</li><li>Jawapan: <b>A</b> (1.6).</li></ol><h5>🔍 Semak jawapan</h5><p>Min 1.6 terletak antara nilai terkecil 0 dan terbesar 4, serta jumlah anggaran 20 × 1.6 = 32 tepat.</p><h5>❌ Mengapa pilihan lain salah</h5><ul><li><b>B</b> (2.0): 2.0: min nilai 0 hingga 4 tanpa mengambil kira kekerapan.</li><li><b>C</b> (4.0): 4.0: 20 ÷ 5 membahagi jumlah murid dengan bilangan lajur.</li><li><b>D</b> (6.4): 6.4: 32 ÷ 5 membahagi jumlah adik-beradik dengan bilangan lajur.</li></ul><h5>📌 Tip peperiksaan</h5><p>Dalam jadual kekerapan, penyebut min ialah jumlah kekerapan, bukan bilangan lajur.</p>",
"<h5>🧭 Faham soalan</h5><p>Perjalanan pertama sejauh 120 km mengambil 1 jam 30 minit; perjalanan kedua 60 km mengambil 1 jam. Cari laju purata seluruh perjalanan.</p><h5>💡 Strategi</h5><p>Laju purata ialah jumlah jarak dibahagi jumlah masa. Tukar minit kepada jam sebelum mengira kerana unit jawapan ialah km/j.</p><h5>✏️ Langkah penyelesaian</h5><ol><li>30 minit = 30 ÷ 60 jam = 0.5 jam; masa pertama = 1 + 0.5 = 1.5 jam.</li><li>Jumlah jarak = 120 + 60 = 180 km. Jumlah masa = 1.5 + 1 = 2.5 jam.</li><li>Laju purata = 180 ÷ 2.5 = 72 km/j.</li><li>Jawapan: <b>B</b> (72 km/j).</li></ol><h5>🔍 Semak jawapan</h5><p>Semak: 72 km/j × 2.5 jam = 180 km, sama dengan jumlah jarak.</p><h5>❌ Mengapa pilihan lain salah</h5><ul><li><b>A</b> (70 km/j): 70 km/j: purata mudah bagi 80 dan 60 km/j; tempoh kedua-dua bahagian tidak sama.</li><li><b>C</b> (78.3 km/j): 78.3 km/j: terhasil jika 1 jam 30 minit tersalah tulis sebagai 1.3 jam.</li><li><b>D</b> (80 km/j): 80 km/j: hanya laju bagi bahagian pertama, 120 ÷ 1.5.</li></ul><h5>📌 Tip peperiksaan</h5><p>Apabila jarak atau masa setiap bahagian berbeza, jumlahkan dahulu sebelum mencari laju purata.</p>",
"<h5>🧭 Faham soalan</h5><p>Carta palang berganda memberi bilangan buku bagi 3 Amanah dan 3 Bestari dari Januari hingga April. Soalan meminta jumlah kedua-dua kelas yang paling tinggi.</p><h5>💡 Strategi</h5><p>Baca kedua-dua palang bagi setiap bulan dan tambah. Membandingkan satu palang sahaja tidak menjawab soalan jumlah.</p><h5>✏️ Langkah penyelesaian</h5><ol><li>Januari: 30 + 25 = 55 buku.</li><li>Februari: 35 + 15 = 50 buku.</li><li>Mac: 15 + 30 = 45 buku.</li><li>April: 30 + 5 = 35 buku.</li><li>Jumlah terbesar ialah 55 buku pada Januari.</li><li>Jawapan: <b>A</b> (Januari).</li></ol><h5>🔍 Semak jawapan</h5><p>Bandingkan 55, 50, 45 dan 35; 55 melebihi semua jumlah lain.</p><h5>❌ Mengapa pilihan lain salah</h5><ul><li><b>B</b> (Februari): Februari: palang 3 Amanah paling tinggi, tetapi jumlahnya 50 sahaja.</li><li><b>C</b> (Mac): Mac: 3 Bestari meminjam 30 buku, tetapi jumlahnya 45 sahaja.</li><li><b>D</b> (April): April: beza antara kelas besar, namun jumlahnya paling kecil, 35.</li></ul><h5>📌 Tip peperiksaan</h5><p>Bagi carta palang berganda, tulis satu jumlah bagi setiap kategori sebelum memilih yang terbesar.</p>",
"<h5>🧭 Faham soalan</h5><p>Rajah menunjukkan tapak 12 cm, tinggi tegak 6 cm dan sisi condong 7.5 cm bagi segi empat selari. Yang dicari ialah luas.</p><h5>💡 Strategi</h5><p>Gunakan luas segi empat selari = tapak × tinggi tegak. Tinggi mesti berserenjang dengan tapak, seperti garis bertanda dalam rajah.</p><h5>✏️ Langkah penyelesaian</h5><ol><li>Baca tapak pada sisi bawah: 12 cm. Baca tinggi tegak pada garis berserenjang: 6 cm.</li><li>Luas = 12 cm × 6 cm = 72 cm².</li><li>Jawapan: <b>C</b> (72 cm²).</li></ol><h5>🔍 Semak jawapan</h5><p>Luas mempunyai unit cm². Sisi condong 7.5 cm tidak diperlukan untuk luas apabila tinggi tegak sudah diberi.</p><h5>❌ Mengapa pilihan lain salah</h5><ul><li><b>A</b> (36 cm²): 36 cm²: ½ × 12 × 6 ialah rumus luas segi tiga.</li><li><b>B</b> (39 cm²): 39 cm²: 2 × (12 + 7.5) ialah perimeter, bukan luas.</li><li><b>D</b> (90 cm²): 90 cm²: 12 × 7.5 menggunakan sisi condong sebagai tinggi.</li></ul><h5>📌 Tip peperiksaan</h5><p>Cari tanda sudut tegak pada rajah untuk mengenal pasti tinggi sebenar.</p>",
"<h5>🧭 Faham soalan</h5><p>Bentangan kubus mempunyai muka 1 dan 2 pada baris atas, muka 3 di bawah muka 2 dan muka 4 di sebelah kanan muka 3, serta muka 5 di bawah muka 4 dan muka 6 di sebelah kanan muka 5. Cari muka bertentangan dengan muka 2.</p><h5>💡 Strategi</h5><p>Lipat bentangan selangkah demi selangkah di sepanjang sisi yang bercantum. Muka yang berkongsi rusuk akan bersebelahan, bukan bertentangan.</p><h5>✏️ Langkah penyelesaian</h5><ol><li>Jadikan muka 4 sebagai tapak. Muka 3 naik menjadi dinding kiri dan muka 5 naik menjadi dinding hadapan.</li><li>Muka 6 yang bercantum pada muka 5 menjadi dinding kanan, jadi muka 3 bertentangan dengan muka 6.</li><li>Muka 2 yang bercantum pada muka 3 menjadi dinding belakang. Dinding belakang bertentangan dengan dinding hadapan, jadi muka 2 bertentangan dengan muka 5.</li><li>Muka 1 yang bercantum pada muka 2 menjadi bahagian atas, bertentangan dengan tapak muka 4.</li><li>Jawapan: <b>D</b> (5).</li></ol><h5>🔍 Semak jawapan</h5><p>Pasangan muka bertentangan ialah 1 dengan 4, 2 dengan 5 dan 3 dengan 6. Setiap muka mempunyai tepat satu muka bertentangan.</p><h5>❌ Mengapa pilihan lain salah</h5><ul><li><b>A</b> (1): bersambung terus dengan muka 2, maka kedua-duanya bersebelahan.</li><li><b>B</b> (3): bersambung terus dengan muka 2, maka kedua-duanya bersebelahan.</li><li><b>C</b> (4): muka ini bertentangan dengan muka 1, bukan muka 2.</li></ul><h5>📌 Tip peperiksaan</h5><p>Lakar semula bentangan ringkas; tandakan muka yang berkongsi rusuk sebelum mencari pasangan bertentangan.</p>",
"<h5>🧭 Faham soalan</h5><p>Ada 9 syiling; tepat satu lebih berat. Neraca dua lengan boleh menunjukkan kiri berat, kanan berat atau seimbang. Cari bilangan penimbangan minimum yang pasti berjaya.</p><h5>💡 Strategi</h5><p>Bahagi sembilan syiling kepada tiga kumpulan sama besar. Setiap penimbangan mempunyai tiga hasil, jadi pembahagian tiga memaksimumkan maklumat.</p><h5>✏️ Langkah penyelesaian</h5><ol><li>Bahagi kepada kumpulan I, II dan III, masing-masing 3 syiling. Timbang I melawan II.</li><li>Jika satu lengan turun, syiling palsu ada dalam kumpulan pada lengan itu. Jika seimbang, syiling palsu ada dalam III. Tinggal 3 calon.</li><li>Timbang satu calon melawan satu calon lain. Yang lebih berat ialah palsu; jika seimbang, calon ketiga ialah palsu.</li><li>Satu penimbangan hanya membezakan 3 hasil, kurang daripada 9 calon. Oleh itu minimum ialah 2.</li><li>Jawapan: <b>B</b> (2).</li></ol><h5>🔍 Semak jawapan</h5><p>Dua penimbangan memberi sehingga 3 × 3 = 9 laluan keputusan, cukup untuk 9 syiling.</p><h5>❌ Mengapa pilihan lain salah</h5><ul><li><b>A</b> (1): hanya tiga hasil, tidak cukup membezakan sembilan syiling.</li><li><b>C</b> (3): kaedah membahagi 4 lawan 4 boleh memerlukan tiga penimbangan dalam kes terburuk, tetapi pembahagian tiga kumpulan menjamin jawapan dalam dua penimbangan, jadi 3 bukan minimum.</li><li><b>D</b> (4): lebih banyak daripada bilangan minimum yang diperlukan kerana dua penimbangan sudah menjamin jawapan.</li></ul><h5>📌 Tip peperiksaan</h5><p>Apabila neraca mempunyai tiga hasil, cuba kumpulan tiga yang sama besar.</p>",
"<h5>🧭 Faham soalan</h5><p>Rajah menunjukkan 1 meja menyediakan 4 kerusi, 2 meja 6 kerusi dan 3 meja 8 kerusi. Seramai 58 tetamu perlu duduk pada satu baris meja.</p><h5>💡 Strategi</h5><p>Setiap meja tambahan menambah dua tempat duduk kerana sisi sambungan tidak boleh digunakan. Bentuk rumus kerusi untuk n meja.</p><h5>✏️ Langkah penyelesaian</h5><ol><li>Bagi n meja, ada n kerusi di atas dan n di bawah, serta 2 di kedua-dua hujung. Jumlah kerusi = 2n + 2.</li><li>Perlu sekurang-kurangnya 58 kerusi: 2n + 2 ≥ 58. Tolak 2: 2n ≥ 56. Bahagi 2: n ≥ 28.</li><li>Dengan 28 meja, kerusi = 2 × 28 + 2 = 58. Maka minimum ialah 28 meja.</li><li>Jawapan: <b>C</b> (28).</li></ol><h5>🔍 Semak jawapan</h5><p>Dengan 27 meja hanya ada 2 × 27 + 2 = 56 kerusi, jadi 28 benar-benar minimum.</p><h5>❌ Mengapa pilihan lain salah</h5><ul><li><b>A</b> (30): 30: memberi 62 kerusi, lebih meja daripada yang diperlukan.</li><li><b>B</b> (29): 29: memberi 60 kerusi; masih cukup tetapi bukan minimum.</li><li><b>D</b> (15): 15: memberi 32 kerusi sahaja; 58 ÷ 4 menganggap meja berasingan.</li></ul><h5>📌 Tip peperiksaan</h5><p>Bagi pola tempat duduk, kira pertambahan apabila satu meja disambung, bukan darab terus dengan tempat duduk meja tunggal.</p>",
"<h5>🧭 Faham soalan</h5><p>Dua neraca seimbang. Daripada rajah, neraca pertama memberi K = 2T + 300 g, dan neraca kedua memberi K + T = 1 200 g. Cari jisim kotak K.</p><h5>💡 Strategi</h5><p>Terjemah imbangan kepada persamaan. Gantikan ungkapan K daripada neraca pertama ke dalam persamaan kedua untuk mencari T.</p><h5>✏️ Langkah penyelesaian</h5><ol><li>K = 2T + 300. Gantikan dalam K + T = 1 200: (2T + 300) + T = 1 200.</li><li>3T + 300 = 1 200, maka 3T = 1 200 − 300 = 900. Jadi T = 900 ÷ 3 = 300 g.</li><li>K = 2 × 300 + 300 = 900 g.</li><li>Jawapan: <b>D</b> (900 g).</li></ol><h5>🔍 Semak jawapan</h5><p>Semak neraca kedua: K + T = 900 + 300 = 1 200 g. Neraca pertama: 2 × 300 + 300 = 900 g.</p><h5>❌ Mengapa pilihan lain salah</h5><ul><li><b>A</b> (300 g): ini jisim satu tin T, bukan kotak K.</li><li><b>B</b> (600 g): hanya jisim dua tin, tanpa pemberat 300 g.</li><li><b>C</b> (750 g): diperoleh dengan menambah kedua-dua pemberat lalu membahagi dua, (1 200 + 300) ÷ 2 = 750, sedangkan kedua-dua persamaan mesti diselesaikan serentak.</li></ul><h5>📌 Tip peperiksaan</h5><p>Tulis satu persamaan bagi setiap neraca; tanda sama dengan bermaksud kedua-dua belah berjisim sama.</p>",
"<h5>🧭 Faham soalan</h5><p>Jadual tarif menetapkan 200 kWj pertama pada RM 0.20, 100 kWj berikutnya pada RM 0.35 dan selebihnya pada RM 0.50. Penggunaan ialah 365 kWj, kemudian cukai 6% dikenakan.</p><h5>💡 Strategi</h5><p>Kira setiap blok penggunaan pada kadar masing-masing. Cukai dikenakan selepas semua caj elektrik dijumlahkan.</p><h5>✏️ Langkah penyelesaian</h5><ol><li>Blok pertama: 200 × RM 0.20 = RM 40.00.</li><li>Blok kedua: 100 × RM 0.35 = RM 35.00. Baki penggunaan = 365 − 200 − 100 = 65 kWj.</li><li>Blok ketiga: 65 × RM 0.50 = RM 32.50. Jumlah caj = RM 40.00 + RM 35.00 + RM 32.50 = RM 107.50.</li><li>Cukai = 6% × RM 107.50 = RM 6.45. Bil akhir = RM 107.50 + RM 6.45 = RM 113.95.</li><li>Jawapan: <b>C</b> (RM 113.95).</li></ol><h5>🔍 Semak jawapan</h5><p>Semak blok: 200 + 100 + 65 = 365 kWj. Bil akhir melebihi caj sebelum cukai sebanyak tepat 6%.</p><h5>❌ Mengapa pilihan lain salah</h5><ul><li><b>A</b> (RM 193.45): RM 193.45: menggunakan kadar tertinggi untuk semua 365 kWj, kemudian menambah cukai.</li><li><b>B</b> (RM 182.50): RM 182.50: 365 × RM 0.50, tanpa tarif berperingkat dan cukai.</li><li><b>D</b> (RM 107.50): RM 107.50: jumlah caj elektrik sebelum cukai.</li></ul><h5>📌 Tip peperiksaan</h5><p>Bagi tarif berperingkat, bahagi penggunaan kepada blok sebelum mendarab kadar.</p>",
"<h5>🧭 Faham soalan</h5><p>Jarak Kuala Lumpur ke Ipoh ialah 205 km sehala. Kereta menggunakan 6 liter bagi 100 km, dan petrol berharga RM 2.05 seliter. Cari kos pergi balik.</p><h5>💡 Strategi</h5><p>Gandakan jarak sehala dahulu. Gunakan kadar liter bagi setiap 100 km untuk mendapat penggunaan petrol, kemudian darab harga seliter.</p><h5>✏️ Langkah penyelesaian</h5><ol><li>Jarak pergi balik = 2 × 205 km = 410 km.</li><li>Penggunaan petrol = 410 ÷ 100 × 6 = 4.1 × 6 = 24.6 liter.</li><li>Kos petrol = 24.6 × RM 2.05 = RM 50.43. Pembundaran kepada dua tempat perpuluhan kekal RM 50.43.</li><li>Jawapan: <b>RM 50.43</b>.</li></ol><h5>🔍 Semak jawapan</h5><p>Semak kos sehala: 205 ÷ 100 × 6 × RM 2.05 = RM 25.215. Dua hala = RM 50.43 apabila dibundarkan pada akhir pengiraan.</p><h5>⚠️ Kesilapan biasa</h5><ul><li>Mengira jarak sehala sahaja akan menghasilkan kos yang terlalu kecil.</li><li>Mendarab 410 dengan 6 tanpa membahagi 100 tersalah tafsir kadar liter bagi setiap 100 km.</li></ul><h5>📌 Tip peperiksaan</h5><p>Jangan bundarkan kos sehala terlalu awal; kira kos keseluruhan dahulu untuk ketepatan dua tempat perpuluhan.</p>",
"<h5>🧭 Faham soalan</h5><p>Seorang murid dipilih hanya daripada ahli Kelab Sains. Jadual menunjukkan 12 murid Tingkatan 2 dan 15 murid Tingkatan 3 dalam kelab itu.</p><h5>💡 Strategi</h5><p>Kebarangkalian = bilangan hasil yang dikehendaki ÷ bilangan semua hasil yang mungkin. Ruang sampel terhad kepada Kelab Sains.</p><h5>✏️ Langkah penyelesaian</h5><ol><li>Jumlah ahli Kelab Sains = 12 + 15 = 27 orang.</li><li>Hasil yang dikehendaki ialah 15 ahli Tingkatan 3. Jadi kebarangkalian = 15 ÷ 27 = 15/27.</li><li>Permudahkan pembilang dan penyebut dengan 3: 15/27 = 5/9.</li><li>Jawapan: <b>A</b> (5/9).</li></ol><h5>🔍 Semak jawapan</h5><p>Semak 5/9 berada antara 0 dan 1. Bilangan 15 daripada 27 memang lebih separuh, selaras dengan 5/9.</p><h5>❌ Mengapa pilihan lain salah</h5><ul><li><b>B</b> (3/8): 3/8: 15/40 menggunakan semua murid Tingkatan 3 sebagai penyebut.</li><li><b>C</b> (27/80): 27/80: kebarangkalian memilih ahli Kelab Sains daripada semua murid.</li><li><b>D</b> (3/16): 3/16: 15/80 menggunakan semua murid sebagai penyebut.</li></ul><h5>📌 Tip peperiksaan</h5><p>Gariskan frasa “daripada ahli Kelab Sains” untuk menentukan ruang sampel yang betul.</p>",
"<h5>🧭 Faham soalan</h5><p>O ialah pusat bulatan; OA dan OB ialah jejari. Sudut OAB ialah 34°, dan sudut ACB pada lilitan yang dicari.</p><h5>💡 Strategi</h5><p>Segi tiga OAB sama kaki kerana dua jejari sama panjang. Cari sudut di pusat AOB, kemudian gunakan teorem sudut di lilitan.</p><h5>✏️ Langkah penyelesaian</h5><ol><li>OA = OB, maka ∠OBA = ∠OAB = 34°.</li><li>Jumlah sudut segi tiga ialah 180°: ∠AOB = 180° − 34° − 34° = 112°.</li><li>Sudut ACB menghadap lengkok AB yang sama. ∠ACB = 112° ÷ 2 = 56°.</li><li>Jawapan: <b>B</b> (56°).</li></ol><h5>🔍 Semak jawapan</h5><p>Semak: sudut di pusat 112° adalah dua kali sudut di lilitan 56°, seperti yang dikehendaki teorem.</p><h5>❌ Mengapa pilihan lain salah</h5><ul><li><b>A</b> (34°): 34°: menyalin sudut di tapak segi tiga tanpa menggunakan teorem bulatan.</li><li><b>C</b> (68°): 68°: menggandakan 34° secara terus; sudut pusat sebenar 112°.</li><li><b>D</b> (112°): 112°: ini sudut di pusat AOB, bukan sudut di lilitan ACB.</li></ul><h5>📌 Tip peperiksaan</h5><p>Dalam rajah bulatan, tandakan jejari yang sama panjang sebelum mengira sudut di pusat.</p>",
"<h5>🧭 Faham soalan</h5><p>Semua ahli Kelab Robotik pandai mengekod. Sebahagian ahli kelab itu juga pengawas. Cari pernyataan yang mesti benar daripada dua maklumat tersebut.</p><h5>💡 Strategi</h5><p>Gunakan pertindihan kumpulan: ahli Robotik yang merupakan pengawas mewarisi sifat semua ahli Robotik, iaitu pandai mengekod.</p><h5>✏️ Langkah penyelesaian</h5><ol><li>Ambil seorang daripada pengawas yang juga ahli Kelab Robotik; kumpulan ini wujud kerana sebahagian ahli Robotik ialah pengawas.</li><li>Oleh sebab semua ahli Robotik pandai mengekod, pengawas tersebut juga pandai mengekod.</li><li>Maka sekurang-kurangnya sebahagian pengawas sekolah pandai mengekod.</li><li>Jawapan: <b>D</b> (Sebahagian pengawas sekolah pandai mengekod).</li></ol><h5>🔍 Semak jawapan</h5><p>Bayangkan dua bulatan, Robotik dan pengawas, yang bertindih. Seluruh bulatan Robotik berada dalam kumpulan murid yang pandai mengekod, jadi bahagian pertindihan itu pasti pandai mengekod.</p><h5>❌ Mengapa pilihan lain salah</h5><ul><li><b>A</b>: maklumat hanya menjamin pengawas dalam pertindihan dengan Kelab Robotik, bukan semua pengawas lain.</li><li><b>B</b>: pernyataan ini menterbalikkan hubungan; murid yang pandai mengekod mungkin bukan ahli Kelab Robotik.</li><li><b>C</b>: bercanggah dengan pernyataan bahawa semua ahli Kelab Robotik pandai mengekod.</li></ul><h5>📌 Tip peperiksaan</h5><p>Bezakan semua daripada sebahagian; jangan songsangkan implikasi tanpa bukti.</p>",
"<h5>🧭 Faham soalan</h5><p>Kumar menyimpan RM 5 pada minggu pertama dan menaikkan simpanan RM 3 setiap minggu. Cari jumlah simpanan sepanjang 20 minggu.</p><h5>💡 Strategi</h5><p>Ini janjang aritmetik dengan beza tetap. Cari simpanan minggu terakhir, kemudian gunakan purata sebutan pertama dan terakhir didarab bilangan minggu.</p><h5>✏️ Langkah penyelesaian</h5><ol><li>Minggu ke-20 berada 19 kenaikan selepas minggu pertama: 5 + 19 × 3 = RM 62.</li><li>Purata simpanan minggu pertama dan terakhir = (5 + 62) ÷ 2 = RM 33.50.</li><li>Jumlah 20 minggu = 20 × RM 33.50 = RM 670.</li><li>Jawapan: <b>B</b> (RM 670).</li></ol><h5>🔍 Semak jawapan</h5><p>Semak rumus lain: 20 × 5 + (0 + 1 + … + 19) × 3 = 100 + 190 × 3 = RM 670.</p><h5>❌ Mengapa pilihan lain salah</h5><ul><li><b>A</b> (RM 62): RM 62: hanya simpanan minggu ke-20.</li><li><b>C</b> (RM 700): RM 700: menggunakan 20 kenaikan, sedangkan minggu ke-20 mempunyai 19 kenaikan.</li><li><b>D</b> (RM 1 240): RM 1 240: 20 × 62 menganggap setiap minggu menyimpan sebanyak minggu terakhir.</li></ul><h5>📌 Tip peperiksaan</h5><p>Sebutan ke-n bagi janjang aritmetik ialah sebutan pertama + (n − 1) × beza.</p>",
"<h5>🧭 Faham soalan</h5><p>Harga asal set periuk tidak diketahui. Diskaun 20% diberi dahulu, kemudian cukai jualan 10% dikenakan pada harga selepas diskaun. Bayaran akhir RM 66.</p><h5>💡 Strategi</h5><p>Gunakan faktor harga berturutan: tinggal 80% selepas diskaun, kemudian darab 110% untuk cukai. Selesaikan secara songsang.</p><h5>✏️ Langkah penyelesaian</h5><ol><li>Ambil harga asal sebagai P. Harga selepas diskaun = 0.80P.</li><li>Bayaran selepas cukai = 1.10 × 0.80P = 0.88P. Maka 0.88P = RM 66.</li><li>P = RM 66 ÷ 0.88 = RM 75.00.</li><li>Jawapan: <b>C</b> (RM 75.00).</li></ol><h5>🔍 Semak jawapan</h5><p>Semak: RM 75.00 − 20% × RM 75.00 = RM 60.00; cukai 10% × RM 60.00 = RM 6.00; jumlah RM 66.00.</p><h5>❌ Mengapa pilihan lain salah</h5><ul><li><b>A</b> (RM 72.00): RM 72.00: menambah 20% kepada RM 60, sedangkan diskaun asal perlu disongsangkan dengan bahagi 0.8.</li><li><b>B</b> (RM 73.33): RM 73.33: menganggap kesan bersih ialah tolak 10%; faktor sebenar 0.88.</li><li><b>D</b> (RM 82.50): RM 82.50: RM 66 ÷ 0.8 mengabaikan cukai.</li></ul><h5>📌 Tip peperiksaan</h5><p>Bagi peratus berturutan, darab faktor perubahan mengikut urutan; jangan terus tambah atau tolak peratus.</p>",
"<h5>🧭 Faham soalan</h5><p>Carta pai menunjukkan makanan 108°, sewa 90°, simpanan 36° dan lain-lain 72°. Sektor pengangkutan belum diketahui. Simpanan 36° bernilai RM 360.</p><h5>💡 Strategi</h5><p>Semua sudut carta pai berjumlah 360°. Cari sudut pengangkutan, kemudian gunakan nisbah wang kepada sudut daripada sektor simpanan.</p><h5>✏️ Langkah penyelesaian</h5><ol><li>Jumlah sudut diketahui = 108° + 90° + 36° + 72° = 306°.</li><li>Sudut pengangkutan = 360° − 306° = 54°.</li><li>Simpanan 36° bersamaan RM 360, jadi 1° bersamaan RM 360 ÷ 36 = RM 10.</li><li>Belanja pengangkutan = 54 × RM 10 = RM 540.</li><li>Jawapan: <b>A</b> (RM 540).</li></ol><h5>🔍 Semak jawapan</h5><p>Semak: sektor pengangkutan 54° ialah 54 ÷ 360 = 15% carta; gaji = RM 360 × 360 ÷ 36 = RM 3 600; 15% × RM 3 600 = RM 540.</p><h5>❌ Mengapa pilihan lain salah</h5><ul><li><b>B</b> (RM 1 260): RM 1 260: menggunakan 126°, kerana sektor lain-lain 72° tidak ditolak.</li><li><b>C</b> (RM 1 944): RM 1 944: menggunakan 54 sebagai 54% gaji; 54° sebenarnya 15%.</li><li><b>D</b> (RM 3 600): RM 3 600: ini jumlah gaji, bukan pengangkutan.</li></ul><h5>📌 Tip peperiksaan</h5><p>Carta pai menggunakan darjah; tukar melalui nisbah 360° atau sektor yang nilainya diketahui.</p>",
"<h5>🧭 Faham soalan</h5><p>Bilangan ahli antara 100 dan 150. Apabila dibahagi kepada baris 4, 5 atau 6 orang, bakinya masing-masing 3, 4 dan 5.</p><h5>💡 Strategi</h5><p>Setiap baki kurang satu daripada pembahagi. Tambah 1 kepada bilangan ahli supaya hasilnya boleh dibahagi tepat dengan 4, 5 dan 6.</p><h5>✏️ Langkah penyelesaian</h5><ol><li>Ambil bilangan ahli sebagai N. Maka N + 1 ialah gandaan sepunya bagi 4, 5 dan 6.</li><li>KSTK bagi 4, 5 dan 6 ialah 60. Gandaan dalam lingkungan N + 1, iaitu 101 hingga 151, hanyalah 120.</li><li>Jadi N + 1 = 120 dan N = 120 − 1 = 119.</li><li>Jawapan: <b>A</b> (119).</li></ol><h5>🔍 Semak jawapan</h5><p>Semak: 119 = 4 × 29 + 3; 119 = 5 × 23 + 4; 119 = 6 × 19 + 5. Bilangannya juga antara 100 dan 150.</p><h5>❌ Mengapa pilihan lain salah</h5><ul><li><b>B</b> (120): 120: setiap pembahagian memberi baki 0, bukan 3, 4 dan 5.</li><li><b>C</b> (121): 121: setiap pembahagian memberi baki 1, bukan satu kurang daripada pembahagi.</li><li><b>D</b> (179): 179: memenuhi pola baki, tetapi di luar julat 100 hingga 150.</li></ul><h5>📌 Tip peperiksaan</h5><p>Jika baki sentiasa satu kurang daripada pembahagi, tambah satu dahulu dan cari KSTK.</p>",
"<h5>🧭 Faham soalan</h5><p>Rajah menunjukkan 1 + 3 + 5 + … hingga nombor ganjil ke-n bersamaan n². Yang ditanya ialah jumlah daripada 21 hingga 79 sahaja.</p><h5>💡 Strategi</h5><p>Ambil jumlah semua nombor ganjil dari 1 hingga 79, kemudian tolak nombor ganjil yang mendahului 21. Kaedah ini terus menggunakan pola kuasa dua pada rajah.</p><h5>✏️ Langkah penyelesaian</h5><ol><li>79 ialah nombor ganjil ke-(79 + 1) ÷ 2 = ke-40. Maka 1 + 3 + … + 79 = 40² = 1 600.</li><li>19 ialah nombor ganjil ke-(19 + 1) ÷ 2 = ke-10. Maka 1 + 3 + … + 19 = 10² = 100.</li><li>Jumlah 21 + 23 + … + 79 = 1 600 − 100 = 1 500.</li><li>Jawapan: <b>B</b> (1500).</li></ol><h5>🔍 Semak jawapan</h5><p>Semak dengan janjang aritmetik: bilangan sebutan = (79 − 21) ÷ 2 + 1 = 30; purata = (21 + 79) ÷ 2 = 50; jumlah = 30 × 50 = 1 500.</p><h5>❌ Mengapa pilihan lain salah</h5><ul><li><b>A</b> (1479): 1479: menolak 11², lalu turut membuang 21.</li><li><b>C</b> (1550): 1550: 31 × 50 mengira 31 sebutan, sedangkan ada 30.</li><li><b>D</b> (1600): 1600: jumlah dari 1 hingga 79 tanpa menolak nombor sebelum 21.</li></ul><h5>📌 Tip peperiksaan</h5><p>Jumlah n nombor ganjil pertama ialah n²; kenal pasti nombor ganjil ke berapa pada kedua-dua hujung.</p>",
"<h5>🧭 Faham soalan</h5><p>Hubungan suhu diberi sebagai F = (9/5)C + 32. Kita mencari bacaan Celsius apabila angka Fahrenheit dua kali angka Celsius.</p><h5>💡 Strategi</h5><p>Gantikan syarat F = 2C ke dalam formula. Kemudian kumpulkan sebutan C untuk menyelesaikan satu persamaan linear.</p><h5>✏️ Langkah penyelesaian</h5><ol><li>Gantikan F dengan 2C: 2C = (9/5)C + 32.</li><li>Tolak (9/5)C: (10/5 − 9/5)C = 32, jadi (1/5)C = 32.</li><li>Darab kedua-dua belah dengan 5: C = 32 × 5 = 160°C.</li><li>Jawapan: <b>C</b> (160°C).</li></ol><h5>🔍 Semak jawapan</h5><p>Semak dalam formula: F = (9/5) × 160 + 32 = 288 + 32 = 320°F; 320 = 2 × 160.</p><h5>❌ Mengapa pilihan lain salah</h5><ul><li><b>A</b> (−40°C): −40°C: suhu apabila bacaan Fahrenheit dan Celsius sama, bukan nisbah dua kali.</li><li><b>B</b> (80°C): 80°C: terhasil jika pekali baki tersalah ambil sebagai 0.4, bukannya 0.2.</li><li><b>D</b> (320°C): 320°C: 320 ialah bacaan Fahrenheit apabila C = 160°C.</li></ul><h5>📌 Tip peperiksaan</h5><p>Apabila dua skala suhu dibandingkan, bezakan nilai F dan C walaupun kedua-duanya nombor.</p>",
"<h5>🧭 Faham soalan</h5><p>Baki kad kredit RM 2 400. Puan Aida membayar 5% daripadanya. Caj kewangan 18% setahun dikenakan pada baki belum dibayar, dan yang dicari caj satu bulan.</p><h5>💡 Strategi</h5><p>Tolak bayaran minimum dahulu kerana caj hanya atas baki. Tukar kadar tahunan kepada kadar bulanan dengan membahagi 12.</p><h5>✏️ Langkah penyelesaian</h5><ol><li>Bayaran minimum = 5% × RM 2 400 = 0.05 × RM 2 400 = RM 120.</li><li>Baki belum dibayar = RM 2 400 − RM 120 = RM 2 280.</li><li>Kadar sebulan = 18% ÷ 12 = 1.5% = 0.015.</li><li>Caj sebulan = 0.015 × RM 2 280 = RM 34.20.</li><li>Jawapan: <b>A</b> (RM 34.20).</li></ol><h5>🔍 Semak jawapan</h5><p>Semak: caj tahunan atas baki yang sama ialah 0.18 × RM 2 280 = RM 410.40; satu bulan ialah RM 410.40 ÷ 12 = RM 34.20.</p><h5>❌ Mengapa pilihan lain salah</h5><ul><li><b>B</b> (RM 36.00): RM 36.00: mengenakan 1.5% pada RM 2 400 penuh sebelum menolak bayaran.</li><li><b>C</b> (RM 410.40): RM 410.40: caj untuk setahun atas RM 2 280, bukan satu bulan.</li><li><b>D</b> (RM 432.00): RM 432.00: caj untuk setahun atas RM 2 400 penuh.</li></ul><h5>📌 Tip peperiksaan</h5><p>Baca asas caj dan tempoh kadar faedah secara berasingan sebelum mendarab.</p>",
"<h5>🧭 Faham soalan</h5><p>Ali berlari pada 5 m/s dan bermula 4 saat lebih awal. Badrul berlari pada 6 m/s dari garisan yang sama. Cari jarak apabila Badrul menyusul Ali.</p><h5>💡 Strategi</h5><p>Cari pendahuluan Ali, kemudian bahagikan dengan beza laju untuk memperoleh masa Badrul mengejar. Jarak pintasan ialah laju Badrul × masa Badrul.</p><h5>✏️ Langkah penyelesaian</h5><ol><li>Pendahuluan Ali selepas 4 s = 5 × 4 = 20 m.</li><li>Laju Badrul melebihi Ali sebanyak 6 − 5 = 1 m/s. Masa mengejar = 20 ÷ 1 = 20 s selepas Badrul bermula.</li><li>Jarak Badrul = 6 × 20 = 120 m.</li><li>Jawapan: <b>C</b> (120 m).</li></ol><h5>🔍 Semak jawapan</h5><p>Pada saat itu Ali telah berlari 4 + 20 = 24 s; jaraknya = 5 × 24 = 120 m. Kedua-duanya berada di tempat sama.</p><h5>❌ Mengapa pilihan lain salah</h5><ul><li><b>A</b> (20 m): 20 m: jarak pendahuluan Ali semasa Badrul bermula.</li><li><b>B</b> (100 m): 100 m: 5 × 20 mengabaikan empat saat awal Ali.</li><li><b>D</b> (144 m): 144 m: 6 × 24 menggunakan masa Ali untuk Badrul.</li></ul><h5>📌 Tip peperiksaan</h5><p>Untuk gerakan sehala, laju relatif ialah beza laju, dan jam setiap pelari bermula pada masa berbeza.</p>",
"<h5>🧭 Faham soalan</h5><p>Min asal 25 murid ialah 152 cm. Satu tinggi 165 cm tersalah catat dan sepatutnya 156 cm. Kemudian murid setinggi 148 cm ditambah; cari min 26 murid.</p><h5>💡 Strategi</h5><p>Tukar min asal kepada jumlah tinggi. Betulkan satu catatan, tambah murid baharu, kemudian bahagi dengan bilangan murid terkini.</p><h5>✏️ Langkah penyelesaian</h5><ol><li>Jumlah tinggi yang tercatat = 25 × 152 = 3 800 cm.</li><li>Pembetulan catatan = 3 800 − 165 + 156 = 3 791 cm.</li><li>Selepas murid baharu: jumlah = 3 791 + 148 = 3 939 cm.</li><li>Min baharu = 3 939 ÷ 26 = 151.5 cm.</li><li>Jawapan: <b>151.5 cm</b>.</li></ol><h5>🔍 Semak jawapan</h5><p>Semak: 151.5 × 26 = 3 939 cm. Min sedikit menurun kerana pembetulan menolak 9 cm dan murid baharu lebih rendah daripada min asal.</p><h5>⚠️ Kesilapan biasa</h5><ul><li>Membetulkan 165 kepada 156 dengan menambah 9 cm menaikkan jumlah secara salah; sepatutnya tolak 9 cm.</li><li>Membahagi jumlah baharu dengan 25 sedangkan sudah ada 26 murid.</li></ul><h5>📌 Tip peperiksaan</h5><p>Bagi min yang berubah, kemas kini jumlah dahulu; jangan ubah min secara terus tanpa mengambil kira bilangan murid.</p>",
"<h5>🧭 Faham soalan</h5><p>Kon terbalik berjejari 6 cm dan tinggi 15 cm penuh air. Air dipindahkan ke silinder berjejari 5 cm dan tinggi 10 cm. Cari kedalaman air.</p><h5>💡 Strategi</h5><p>Isi padu air kekal sama semasa dipindahkan. Samakan isi padu kon dengan isi padu silinder pada kedalaman h.</p><h5>✏️ Langkah penyelesaian</h5><ol><li>Isi padu kon = (1/3) × π × 6² × 15 = (1/3) × π × 36 × 15 = 180π cm³.</li><li>Isi padu air dalam silinder = π × 5² × h = 25πh cm³. Jadi 25πh = 180π.</li><li>Bahagi dengan 25π: h = 180 ÷ 25 = 7.2 cm.</li><li>Jawapan: <b>A</b> (7.2 cm).</li></ol><h5>🔍 Semak jawapan</h5><p>Kedalaman 7.2 cm kurang daripada tinggi silinder 10 cm, maka air muat tanpa melimpah. Isi padu silinder penuh ialah 250π cm³, melebihi 180π cm³.</p><h5>❌ Mengapa pilihan lain salah</h5><ul><li><b>B</b> (10.0 cm): 10.0 cm: menganggap silinder penuh, tetapi air hanya 180π cm³.</li><li><b>C</b> (21.6 cm): 21.6 cm: terlupa faktor 1/3 dalam isi padu kon.</li><li><b>D</b> (28.8 cm): 28.8 cm: menggunakan diameter 12 cm sebagai jejari kon.</li></ul><h5>📌 Tip peperiksaan</h5><p>Isi padu kon mempunyai faktor satu pertiga; semak juga sama ada kedalaman yang dikira melebihi tinggi bekas.</p>",
"<h5>🧭 Faham soalan</h5><p>Kos bas tetap dikongsi 30 murid pada mulanya. Lima murid menarik diri, jadi tinggal 25 murid dan bayaran seorang meningkat RM 4. Cari kos sewa bas.</p><h5>💡 Strategi</h5><p>Nyatakan kos sebagai k. Bayaran seorang ialah kos dibahagi bilangan murid. Bezakan bayaran baharu dan bayaran asal untuk membina persamaan.</p><h5>✏️ Langkah penyelesaian</h5><ol><li>Bilangan murid baharu = 30 − 5 = 25. Bayaran asal = k/30, bayaran baharu = k/25.</li><li>Kenaikan RM 4 memberi k/25 − k/30 = 4. Penyebut sepunya 150: 6k/150 − 5k/150 = 4.</li><li>k/150 = 4, maka k = 4 × 150 = RM 600.</li><li>Jawapan: <b>RM 600</b>.</li></ol><h5>🔍 Semak jawapan</h5><p>Semak: mula-mula RM 600 ÷ 30 = RM 20 seorang; kemudian RM 600 ÷ 25 = RM 24 seorang; kenaikan RM 24 − RM 20 = RM 4.</p><h5>⚠️ Kesilapan biasa</h5><ul><li>Mengira 30 × RM 4 = RM 120 sebagai kos bas, walhal RM 4 hanya kenaikan seorang.</li><li>Mendarab bayaran baharu RM 24 dengan 30 murid asal; bayaran itu untuk 25 murid.</li></ul><h5>📌 Tip peperiksaan</h5><p>Kos tetap bermaksud bilangan murid × bayaran seorang sama sebelum dan selepas perubahan.</p>",
"<h5>🧭 Faham soalan</h5><p>ETS sepanjang 150 m bergerak 108 km/j, manakala kereta api barang sepanjang 210 m bergerak 54 km/j sehala. Cari masa untuk ETS memintas sepenuhnya.</p><h5>💡 Strategi</h5><p>Tukar laju kepada m/s. Oleh sebab kedua-duanya sehala, laju relatif ialah beza laju. Untuk pintasan penuh, jarak relatif ialah jumlah panjang kedua-dua kereta api.</p><h5>✏️ Langkah penyelesaian</h5><ol><li>108 km/j = 108 × 1 000 ÷ 3 600 = 30 m/s. 54 km/j = 54 × 1 000 ÷ 3 600 = 15 m/s.</li><li>Laju relatif = 30 − 15 = 15 m/s. Jarak relatif = 150 + 210 = 360 m.</li><li>Masa = jarak relatif ÷ laju relatif = 360 ÷ 15 = 24 s.</li><li>Jawapan: <b>D</b> (24 s).</li></ol><h5>🔍 Semak jawapan</h5><p>Semak: dalam 24 s, ETS bergerak 30 × 24 = 720 m dan kereta api barang 15 × 24 = 360 m; beza pergerakan 360 m.</p><h5>❌ Mengapa pilihan lain salah</h5><ul><li><b>A</b> (8 s): 8 s: menggunakan jumlah laju 30 + 15 = 45 m/s, sesuai hanya untuk arah bertentangan.</li><li><b>B</b> (10 s): 10 s: 150 ÷ 15 menggunakan panjang ETS sahaja.</li><li><b>C</b> (14 s): 14 s: 210 ÷ 15 menggunakan panjang kereta api barang sahaja.</li></ul><h5>📌 Tip peperiksaan</h5><p>Pintasan penuh dua kenderaan panjang memerlukan jumlah panjangnya sebagai jarak relatif.</p>",
"<h5>🧭 Faham soalan</h5><p>Stor berbentuk segi empat sama bersisi 7 m. Kambing ditambat pada satu bucu dengan tali 14 m. Stor menghalang pergerakan terus melalui sudut dalam, tetapi tali boleh melilit dua bucu bersebelahan.</p><h5>💡 Strategi</h5><p>Bahagi kawasan tercapai kepada sektor utama berjejari 14 m dan dua sektor tambahan berjejari 7 m. Sudut sektor utama diperoleh dengan menolak sudut stor daripada satu bulatan penuh.</p><h5>✏️ Langkah penyelesaian</h5><ol><li>Sudut dalam stor pada bucu tambatan ialah 90°, jadi sudut sektor utama = 360° − 90° = 270°. Luasnya = (3/4) × (22/7) × 14² = (3/4) × (22/7) × 196 = 462 m².</li><li>Baki tali selepas melalui satu sisi stor = 14 − 7 = 7 m. Setiap bucu bersebelahan memberi satu suku bulatan: (1/4) × (22/7) × 7² = 38.5 m².</li><li>Dua sektor tambahan = 2 × 38.5 = 77 m². Jumlah kawasan = 462 + 77 = 539 m².</li><li>Jawapan: <b>D</b> (539 m²).</li></ol><h5>🔍 Semak jawapan</h5><p>Kawasan utama 462 m² dan dua tambahan sama luas 38.5 m² setiap satu memberi jumlah 539 m². Tali yang mengelilingi dua sisi habis tepat pada bucu bertentangan, jadi tiada sektor tambahan di situ.</p><h5>❌ Mengapa pilihan lain salah</h5><ul><li><b>A</b> (462 m²): mengira sektor utama sahaja dan mengabaikan lilitan pada dua bucu.</li><li><b>B</b> (490 m²): menolak luas stor 7 × 7 = 49 m² walaupun sektor utama sudah mengecualikan stor.</li><li><b>C</b> (500.5 m²): 462 + 38.5, hanya mengambil satu bucu bersebelahan.</li></ul><h5>📌 Tip peperiksaan</h5><p>Untuk tali yang melilit halangan, tolak panjang sisi yang dilalui daripada panjang tali bagi setiap sektor baharu.</p>"],
"sains":["<h5>🧠 Konsep utama</h5><p>Sel darah merah (eritrosit) mengalami pengkhususan struktur untuk memaksimumkan fungsinya dalam mengangkut oksigen dari peparu ke seluruh sel badan. Ketiadaan nukleus pada sel darah merah matang menyediakan lebih banyak ruang di dalam sitoplasma untuk memuatkan molekul hemoglobin, iaitu pigmen merah yang mengikat oksigen menjadi oksihemoglobin. Bentuk cakera dwicekung pula meningkatkan nisbah luas permukaan kepada isi padu (J/I) sel. Luas permukaan yang besar ini mempercepat kadar resapan gas oksigen merentasi membran sel ke dalam dan ke luar sel.</p><h5>✅ Mengapa jawapan A betul</h5><p>Ketiadaan nukleus memberikan ruang maksimum kepada hemoglobin, manakala bentuk cakera dwicekung menambah luas permukaan bagi membolehkan resapan oksigen berlaku secara cekap.</p><h5>❌ Mengapa pilihan lain salah</h5><ul><li><b>B</b> — Sel darah merah matang tidak mempunyai nukleus dan tidak boleh membahagi; ia dihasilkan berterusan di dalam sumsum tulang.</li><li><b>C</b> — Memusnahkan bakteria dan patogen ialah peranan sel darah putih (leukosit) melalui fagositosis atau penghasilan antibodi.</li><li><b>D</b> — Pembekuan darah dikendalikan oleh platelet dan protein fibrinogen dalam plasma darah, bukan oleh sel darah merah.</li></ul><h5>📌 Ingat</h5><p>Tanpa nukleus = ruang maksimum untuk hemoglobin; bentuk dwicekung = luas permukaan besar untuk mempercepat resapan oksigen.</p>",
"<h5>🧠 Konsep utama</h5><p>Daun belang (variegasi) mempunyai corak hijau dan putih. Bahagian berwarna hijau mengandungi pigmen klorofil di dalam kloroplasnya, manakala bahagian putih tidak mengandungi klorofil langsung. Apabila pokok ini didedahkan kepada cahaya matahari, semua bahagian daun menerima keamatan cahaya matahari, gas karbon dioksida, dan air yang sama. Klorofil berfungsi menyerap tenaga cahaya yang penting untuk memacu tindak balas fotosintesis bagi menghasilkan glukosa, yang kemudiannya disimpan sebagai kanji. Ujian iodin mengesahkan kehadiran kanji; larutan iodin bertukar warna daripada perang kepada biru tua hanya pada bahagian hijau di mana fotosintesis telah berlaku.</p><h5>✅ Mengapa jawapan B betul</h5><p>Hanya bahagian hijau yang mempunyai klorofil menghasilkan kanji dan memberikan ujian iodin positif (biru tua), membuktikan klorofil diperlukan untuk fotosintesis.</p><h5>❌ Mengapa pilihan lain salah</h5><ul><li><b>A</b> — Seluruh daun terdedah kepada cahaya matahari yang sama; untuk menguji keperluan cahaya, sebahagian daun perlu ditutup dengan kertas hitam.</li><li><b>C</b> — Seluruh daun terdedah kepada udara yang sama; untuk menguji keperluan karbon dioksida, daun diletakkan bersama kalium hidroksida dalam kelalang.</li><li><b>D</b> — Seluruh daun mendapat bekalan air yang sama daripada tangkai daun melalui xilem; air bukan pemboleh ubah yang dimanipulasi di sini.</li></ul><h5>📌 Ingat</h5><p>Eksperimen daun berbelang membuktikan bahawa klorofil sangat penting untuk menjalankan fotosintesis dan menghasilkan kanji.</p>",
"<h5>🧠 Konsep utama</h5><p>Sistem saraf manusia dibahagikan kepada dua bahagian utama, iaitu sistem saraf pusat dan sistem saraf periferi. Sistem saraf pusat bertindak sebagai pusat kawalan utama yang menerima maklumat daripada reseptor deria, mentafsir dan memproses maklumat tersebut, lalu menghantar arahan kepada efektor. Sistem saraf pusat hanya terdiri daripada dua organ penting, iaitu otak dan saraf tunjang. Sebaliknya, sistem saraf periferi terdiri daripada rangkaian saraf yang menghubungkan sistem saraf pusat dengan bahagian badan lain, iaitu saraf kranium dan saraf spina.</p><h5>✅ Mengapa jawapan A betul</h5><p>Sistem saraf pusat manusia secara anatominya terbentuk daripada otak dan saraf tunjang sahaja.</p><h5>❌ Mengapa pilihan lain salah</h5><ul><li><b>B</b> — Saraf kranium ialah gentian saraf periferi yang keluar dari otak, bukan komponen sistem saraf pusat.</li><li><b>C</b> — Saraf spina tergolong dalam sistem saraf periferi yang bercabang keluar dari saraf tunjang.</li><li><b>D</b> — Neuron deria dan neuron motor ialah jenis sel saraf, bukan dua bahagian anatomi yang mentakrifkan sistem saraf pusat. Badan sel atau bahagian neuronnya juga boleh berada dalam sistem saraf pusat.</li></ul><h5>📌 Ingat</h5><p>Sistem saraf pusat terdiri daripada otak dan saraf tunjang. Saraf kranium dan saraf spina pula membentuk sistem saraf periferi.</p>",
"<h5>🧠 Konsep utama</h5><p>Pelawas (serat diet) merupakan karbohidrat kompleks terutamanya selulosa daripada dinding sel tumbuhan yang tidak boleh dicerna oleh enzim dalam sistem pencernaan manusia. Walaupun tidak membekalkan tenaga, pelawas mempunyai keupayaan menyerap sejumlah besar air dan menambah saiz serta kelembutan tinja (feses). Pukal tinja yang cukup akan merangsang pengecutan dan pengenduran otot dinding usus secara beritma, iaitu proses peristalsis, untuk melancarkan penyahtinjaan. Kekurangan pelawas menyebabkan pergerakan tinja menjadi perlahan di dalam kolon, air diserap secara berlebihan, dan tinja menjadi keras serta kering sehingga berlakunya sembelit.</p><h5>✅ Mengapa jawapan C betul</h5><p>Sayur-sayuran dan buah-buahan merupakan sumber utama pelawas; kekurangan pelawas dalam diet menyebabkan kesukaran membuang air besar atau sembelit.</p><h5>❌ Mengapa pilihan lain salah</h5><ul><li><b>A</b> — Kekurangan protein menjejaskan pembentukan sel baharu dan pembaikan tisu, seperti penyakit kwashiorkor.</li><li><b>B</b> — Kekurangan lemak menyebabkan kehilangan penebat haba badan dan kekurangan penyerapan vitamin larut lemak (A, D, E, K).</li><li><b>D</b> — Kekurangan karbohidrat mengakibatkan tubuh kekurangan sumber tenaga utama dan berasa letih.</li></ul><h5>📌 Ingat</h5><p>Pelawas daripada buah dan sayur menyerap air serta merangsang peristalsis usus untuk melancarkan penyahtinjaan dan mencegah sembelit.</p>",
"<h5>🧠 Konsep utama</h5><p>Air liur mengandungi enzim pencernaan iaitu amilase liur yang memangkin penguraian kanji kepada gula ringkas (maltosa). Enzim terbina daripada protein dan mempunyai struktur tiga dimensi serta tapak aktif yang khusus. Aktiviti enzim amat dipengaruhi oleh suhu. Pada suhu badan (37 °C), enzim berfungsi pada tahap optimum. Namun demikian, pada suhu tinggi seperti pendidihan (100 °C), ikatan kimia yang mengekalkan struktur enzim terputus, menyebabkan enzim ternyahasli (rosak) dan tapak aktifnya musnah secara kekal. Oleh itu, air liur yang telah dididihkan dalam tabung uji Q tidak lagi dapat mencernakan kanji, menyebabkan larutan kanji kekal ada dan memberikan ujian iodin biru tua.</p><h5>✅ Mengapa jawapan D betul</h5><p>Enzim amilase liur dalam tabung uji Q telah ternyahasli akibat pendidihan, menjadikannya tidak aktif dan gagal mencernakan kanji.</p><h5>❌ Mengapa pilihan lain salah</h5><ul><li><b>A</b> — Kanji dalam tabung uji Q tidak dicernakan kerana larutan iodin bertukar menjadi biru tua, menunjukkan kanji masih wujud.</li><li><b>B</b> — Larutan iodin tetap bertindak balas dengan kanji pada 37 °C; tabung uji Q jelas memberikan warna biru tua.</li><li><b>C</b> — Air liur tidak mengandungi kanji; sebaliknya air liur membekalkan enzim amilase untuk mencernakan kanji.</li></ul><h5>📌 Ingat</h5><p>Pendidihan menyahaslikan enzim secara kekal kerana haba memusnahkan bentuk tapak aktif enzim sehingga substrat tidak dapat terikat.</p>",
"<h5>🧠 Konsep utama</h5><p>Darah manusia terdiri daripada cecair plasma dan elemen selular iaitu eritrosit (sel darah merah), leukosit (sel darah putih), dan platelet (trombosit). Platelet ialah serpihan sel kecil tanpa nukleus yang dihasilkan di dalam sumsum tulang. Fungsi utama platelet adalah dalam mekanisme hemostasis atau pembekuan darah apabila salur darah mengalami kecederaan atau luka. Apabila berlaku luka, platelet akan melekat pada dinding salur darah yang rosak, membentuk palam platelet, dan membebaskan bahan pembeku (trombokinase). Ini mencetuskan tindak balas berantai yang menukarkan fibrinogen kepada jaring fibrin untuk memerangkap sel darah dan menutup luka.</p><h5>✅ Mengapa jawapan C betul</h5><p>Kekurangan platelet menghalang proses pembekuan darah yang normal, menyebabkan pesakit mengalami pendarahan berterusan apabila luka.</p><h5>❌ Mengapa pilihan lain salah</h5><ul><li><b>A</b> — Pengangkutan oksigen dikendalikan oleh hemoglobin di dalam sel darah merah, bukan platelet.</li><li><b>B</b> — Melawan jangkitan patogen merupakan fungsi sel darah putih melalui fagositosis dan penghasilan antibodi.</li><li><b>D</b> — Pengangkutan nutrien tercerna (seperti glukosa dan asid amino) dijalankan oleh cecair plasma darah.</li></ul><h5>📌 Ingat</h5><p>Fungsi komponen darah: Eritrosit = angkut oksigen, Leukosit = pertahanan badan, Platelet = pembekuan darah, Plasma = angkut nutrien dan sisa.</p>",
"<h5>🧠 Konsep utama</h5><p>Rongga hidung mempunyai struktur khas yang diadaptasi untuk menyediakan udara sedutan sebelum sampai ke saluran pernafasan bawah dan peparu. Dinding dalam rongga hidung dilapisi oleh membran mukus yang mengandungi sel bersilia dan sel perembes mukus. Bulu hidung bersama lapisan mukus yang melekit bertindak sebagai penapis biologi yang memerangkap habuk, kotoran, dan mikroorganisma dalam udara. Di samping itu, kehadiran rangkaian kapilari darah yang banyak membebaskan haba untuk memanaskan udara sedutan sehingga menyamai suhu badan, manakala mukus melembapkan udara tersebut agar tisu peparu tidak kering atau rosak.</p><h5>✅ Mengapa jawapan A betul</h5><p>Rongga hidung menapis zarah habuk dan patogen menggunakan bulu hidung dan mukus, serta memanaskan dan melembapkan udara sedutan.</p><h5>❌ Mengapa pilihan lain salah</h5><ul><li><b>B</b> — Hidung tidak boleh menambah peratusan gas oksigen ke dalam udara yang disedut.</li><li><b>C</b> — Penyingkiran karbon dioksida berlaku melalui hembusan nafas dari alveolus peparu, bukan disingkirkan di dalam rongga hidung.</li><li><b>D</b> — Kelajuan aliran udara bukanlah faedah utama bernafas melalui rongga hidung berbanding mulut.</li></ul><h5>📌 Ingat</h5><p>Rongga hidung menyediakan tiga fungsi penting bagi udara sedutan: menapis (bulu dan mukus), melembapkan (mukus), dan memanaskan (kapilari darah).</p>",
"<h5>🧠 Konsep utama</h5><p>Dalam kitar pembiakan tumbuhan berbunga, proses persenyawaan berlaku apabila gamet jantan dari butir debunga bercantum dengan gamet betina (sel telur) di dalam ovul. Selepas berlakunya persenyawaan, pelbagai perubahan morfologi berlaku pada struktur bunga: Dinding ovari akan membengkak, menebal, dan berkembang menjadi buah (perikarpa buah). Ovul di dalam ovari pula akan berkembang menjadi biji benih yang mengandungi embrio tumbuhan baharu. Bahagian bunga lain seperti kelopak, sepal, stamen, dan stigma biasanya akan layu dan gugur.</p><h5>✅ Mengapa jawapan B betul</h5><p>Selepas persenyawaan berlaku, ovari pada bunga akan membesar dan berkembang membentuk buah.</p><h5>❌ Mengapa pilihan lain salah</h5><ul><li><b>A</b> — Biji benih terhasil daripada perkembangan ovul di dalam ovari, bukannya daripada ovari itu sendiri.</li><li><b>C</b> — Butir debunga dihasilkan di dalam anter pada organ jantan (stamen) sebelum proses pendebungaan berlaku.</li><li><b>D</b> — Kelopak bunga biasanya akan layu dan gugur selepas persenyawaan selesai.</li></ul><h5>📌 Ingat</h5><p>Perkembangan struktur bunga selepas persenyawaan: Ovari berkembang menjadi buah, manakala ovul berkembang menjadi biji benih.</p>",
"<h5>🧠 Konsep utama</h5><p>Percambahan biji benih memerlukan tiga faktor persekitaran yang penting, iaitu air, udara (oksigen), dan suhu yang sesuai (kehangatan). Oksigen diperlukan untuk proses respirasi sel bagi membebaskan tenaga yang membolehkan embrio berkembang. Untuk menyiasat bahawa oksigen ialah faktor yang diperlukan, eksperimen terkawal mesti dijalankan di mana oksigen dijadikan pemboleh ubah dimanipulasikan sementara air dan suhu dimalarkan. Tabung uji P dibekalkan dengan kapas lembap (ada air), suhu bilik 30 °C (suhu sesuai), dan terdedah kepada udara (ada oksigen). Tabung uji R mempunyai air dan suhu 30 °C, tetapi ketiadaan oksigen kerana air yang dididihkan bebas daripada oksigen terlarut dan lapisan minyak menghalang udara luar daripada meresap masuk.</p><h5>✅ Mengapa jawapan D betul</h5><p>Perbandingan antara tabung uji P (ada oksigen) dan tabung uji R (tiada oksigen) dengan faktor air dan suhu dimalarkan membuktikan oksigen diperlukan untuk percambahan.</p><h5>❌ Mengapa pilihan lain salah</h5><ul><li><b>A</b> — Perbandingan antara P (lembap) dan Q (kering) menguji keperluan air terhadap percambahan biji benih.</li><li><b>B</b> — Perbandingan antara P (30 °C) dan S (4 °C) menguji keperluan suhu yang sesuai untuk percambahan.</li><li><b>C</b> — Tabung uji Q dan R berbeza dari segi dua pemboleh ubah serentak (air dan oksigen), menjadikannya bukan eksperimen terkawal yang adil.</li></ul><h5>📌 Ingat</h5><p>Air didih menyingkirkan oksigen terlarut dan lapisan minyak menghalang resapan oksigen dari udara untuk mewujudkan persekitaran tanpa oksigen.</p>",
"<h5>🧠 Konsep utama</h5><p>Dalam bidang ekologi, organisasi hidupan disusun mengikut peringkat hierarki tertentu daripada individu sehinggalah kepada biosfera. Spesies merujuk kepada sekumpulan organisma serupa yang boleh saling membiak dan menghasilkan anak yang subur. Populasi ditakrifkan sebagai sekumpulan organisma daripada spesies yang sama yang hidup bersama-sama di dalam satu habitat yang sama pada masa tertentu. Komuniti pula merangkumi semua populasi organisma daripada pelbagai spesies berbeza yang berinteraksi di habitat tersebut. Ekosistem merangkumi komuniti hidupan berserta interaksinya dengan faktor abiotik seperti air, tanah, dan udara.</p><h5>✅ Mengapa jawapan C betul</h5><p>Semua ikan keli tergolong dalam spesies yang sama dan mendiami habitat yang sama (kolam), maka mereka membentuk satu populasi.</p><h5>❌ Mengapa pilihan lain salah</h5><ul><li><b>A</b> — Komuniti terdiri daripada gabungan pelbagai spesies hidupan yang berlainan di dalam kolam itu (seperti ikan keli, lumut, teratai, dan katak).</li><li><b>B</b> — Ekosistem melibatkan keseluruhan interaksi antara semua organisma hidup (komuniti) dengan faktor bukan hidup di kolam tersebut.</li><li><b>D</b> — Kolam itu sendiri merupakan habitat (tempat tinggal fizikal), bukan organisma yang membentuk kumpulan tersebut.</li></ul><h5>📌 Ingat</h5><p>Spesies yang sama di habitat yang sama = Populasi. Gabungan pelbagai populasi yang berbeza = Komuniti.</p>",
"<h5>🧠 Konsep utama</h5><p>Penguraian bahan organik mati merupakan proses biokimia penting dalam kitar nutrien ekosistem. Pengurai, terutamanya bakteria tanah dan kulat mikroskopik (mikroorganisma saprofit), merembeskan enzim untuk menguraikan sebatian organik kompleks daripada daun kering kepada nutrien ringkas. Dalam bekas P, tanah kebun biasa mengandungi mikroorganisma pengurai yang aktif, menyebabkan daun reput sepenuhnya dalam empat minggu. Dalam bekas Q, pemanasan tanah dalam ketuhar telah mengurangkan atau membunuh kebanyakan mikroorganisma pengurai di dalam tanah. Aktiviti penguraian dalam bekas Q menjadi jauh lebih perlahan, maka daun hampir tidak berubah.</p><h5>✅ Mengapa jawapan A betul</h5><p>Daun dalam P reput manakala daun dalam tanah yang dipanaskan Q hampir tidak reput membuktikan bahawa mikroorganisma di dalam tanah bertanggungjawab menguraikan daun kering.</p><h5>❌ Mengapa pilihan lain salah</h5><ul><li><b>B</b> — Pemanasan tanah digunakan untuk mensterilkan tanah sebelum eksperimen; semasa pemerhatian kedua-dua bekas berada pada suhu bilik yang sama.</li><li><b>C</b> — Proses penguraian oleh bakteria dan kulat tanah tidak memerlukan cahaya matahari.</li><li><b>D</b> — Daun dalam Q tidak reput bukan kerana kekurangan nutrien tanah, tetapi kerana mikroorganisma pengurai telah mati dimusnahkan haba.</li></ul><h5>📌 Ingat</h5><p>Pemanasan mengurangkan mikroorganisma pengurai dalam tanah; akibatnya pereputan daun menjadi jauh lebih perlahan.</p>",
"<h5>🧠 Konsep utama</h5><p>Pemuliharaan biodiversiti bertujuan melindungi hidupan liar terancam daripada kepupusan. Kaedah pemuliharaan terbahagi kepada pemuliharaan di habitat asal dan di luar habitat asal. Bagi pemangsa puncak seperti Harimau Malaya (<i>Panthera tigris jacksoni</i>), pemuliharaan di habitat asal merupakan kaedah yang paling berkesan dan mampan. Harimau memerlukan kawasan wilayah perayauan hutan hujan yang sangat luas, padat dengan sumber mangsa semula jadi dan terlindung daripada gangguan manusia. Pewartaan hutan simpan dan taman negara mengelakkan pemecahan habitat, manakala rondaan ketat dan penguatkuasaan undang-undang menghalang pemburuan haram.</p><h5>✅ Mengapa jawapan C betul</h5><p>Mewartakan hutan simpan serta menguatkuasakan undang-undang perlindungan haiwan secara tegas memelihara habitat semula jadi dan melindungi harimau daripada diburu.</p><h5>❌ Mengapa pilihan lain salah</h5><ul><li><b>A</b> — Penerokaan hutan untuk pertanian memusnahkan habitat semula jadi dan memecahbelahkan kawasan perayauan harimau.</li><li><b>B</b> — Harimau ialah karnivor liar pemangsa yang berbahaya dan tidak boleh dijinakkan atau dibela di rumah, serta menyalahi undang-undang.</li><li><b>D</b> — Memindahkan spesies asli ke negara luar menjejaskan keseimbangan ekosistem tempatan dan bukan kaedah pemuliharaan di habitat asal yang betul.</li></ul><h5>📌 Ingat</h5><p>Pemuliharaan in-situ melalui perlindungan hutan simpan dan banteras pemburuan haram merupakan strategi paling berkesan menyelamatkan spesies terancam.</p>",
"<h5>🧠 Konsep utama</h5><p>Keadaan fizikal sesuatu jirim pada suhu tertentu ditentukan oleh takat lebur dan takat didih bahan tersebut: 1. Jika suhu persekitaran lebih rendah daripada takat lebur (T < takat lebur), bahan wujud sebagai pepejal. 2. Jika suhu persekitaran berada di antara takat lebur dan takat didih (takat lebur < T < takat didih), bahan wujud sebagai cecair. 3. Jika suhu persekitaran lebih tinggi daripada takat didih (T > takat didih), bahan wujud sebagai gas. Pada suhu bilik 27 °C: Bahan P mempunyai takat lebur −10 °C dan takat didih 60 °C. Kerana −10 °C < 27 °C < 60 °C, bahan P wujud sebagai cecair.</p><h5>✅ Mengapa jawapan A betul</h5><p>Suhu bilik 27 °C berada di antara takat lebur (−10 °C) dan takat didih (60 °C) bagi bahan P, menjadikannya wujud dalam keadaan cecair.</p><h5>❌ Mengapa pilihan lain salah</h5><ul><li><b>B</b> — Bahan Q mempunyai takat lebur 40 °C, jadi pada suhu 27 °C ia masih belum melebur dan wujud sebagai pepejal.</li><li><b>C</b> — Bahan R mempunyai takat didih −150 °C, jadi pada 27 °C ia telah lama mendidih dan wujud sebagai gas.</li><li><b>D</b> — Bahan S mempunyai takat lebur 120 °C, jadi pada suhu 27 °C ia wujud sebagai pepejal.</li></ul><h5>📌 Ingat</h5><p>Penentuan keadaan jirim: Suhu < Takat Lebur = Pepejal; Takat Lebur < Suhu < Takat Didih = Cecair; Suhu > Takat Didih = Gas.</p>",
"<h5>🧠 Konsep utama</h5><p>Kromatografi kertas ialah kaedah pemisahan fizikal yang digunakan untuk mengasingkan dan menganalisis komponen dalam campuran yang larut, terutamanya bahan berwarna seperti pewarna dan dakwat. Prinsip kromatografi bergantung kepada perbezaan tahap keterlarutan setiap komponen dalam pelarut bergerak (fasa bergerak) dan tahap penjerapan pada kertas kromatografi (fasa pegun). Komponen pewarna yang lebih mudah larut dalam pelarut akan meresap dan bergerak lebih pantas dan lebih jauh ke atas kertas. Dakwat yang mengandungi campuran pewarna yang berbeza boleh menghasilkan corak tompok yang berbeza. Jika dua sampel menghasilkan corak tompok yang sepadan dalam keadaan ujian yang sama, kedua-duanya mungkin daripada jenis dakwat yang sama; corak itu sahaja tidak membuktikan sumbernya sama.</p><h5>✅ Mengapa jawapan C betul</h5><p>Kromatografi kertas memisahkan pewarna-pewarna dalam dakwat untuk dibandingkan corak tompok warnanya antara dakwat surat dengan dakwat pen suspek.</p><h5>❌ Mengapa pilihan lain salah</h5><ul><li><b>A</b> — Penurasan hanya digunakan untuk memisahkan pepejal tak larut daripada cecair, bukan memisahkan pewarna terlarut.</li><li><b>B</b> — Penyulingan digunakan untuk mengasingkan campuran cecair berasaskan perbezaan takat didih yang ketara.</li><li><b>D</b> — Penyejatan digunakan untuk memperoleh pepejal terlarut dengan menyejat pelarut cecair, bukan untuk membezakan jenis dakwat.</li></ul><h5>📌 Ingat</h5><p>Kromatografi kertas ialah teknik khusus untuk memisahkan dan membandingkan campuran pewarna atau pigmen dalam dakwat.</p>",
"<h5>🧠 Konsep utama</h5><p>Tindak balas pembakaran ialah tindak balas kimia eksotermik antara bahan api dengan oksigen yang membebaskan tenaga haba dan cahaya. Pembakaran hanya boleh berlaku sekiranya ketiga-tiga komponen dalam 'segi tiga kebakaran' hadir secara serentak, iaitu: bahan api, oksigen, dan haba (suhu pencucuhan). Jika salah satu daripada tiga syarat ini disingkirkan, pembakaran akan terhenti dan api akan terpadam serta-merta. Menutup kuali yang terbakar dengan kain basah yang tebal merupakan kaedah melemaskan api. Kain basah membentuk penghadang fizikal yang menyekat udara atmosfera daripada bersentuhan dengan permukaan minyak yang sedang marak.</p><h5>✅ Mengapa jawapan A betul</h5><p>Kain basah menyelimuti kuali dan menghalang bekalan gas oksigen daripada sampai ke bahan api, menyebabkan api terpadam.</p><h5>❌ Mengapa pilihan lain salah</h5><ul><li><b>B</b> — Minyak masak bertindak sebagai bahan api dan masih berada di dalam kuali, jadi bahan api tidak disingkirkan.</li><li><b>C</b> — Kain basah tidak menambahkan bahan api; penambahan bahan api sebaliknya akan menyemarakkan lagi api.</li><li><b>D</b> — Kain basah tidak membebaskan gas karbon dioksida; fungsi utamanya adalah menghalang kemasukan oksigen.</li></ul><h5>📌 Ingat</h5><p>Segi tiga kebakaran: Oksigen, Haba, dan Bahan Api. Menutup kuali dengan kain basah memadamkan api secara melemaskan (menyekat oksigen).</p>",
"<h5>🧠 Konsep utama</h5><p>Elektrolisis air ialah proses penguraian molekul air (H₂O) kepada gas juzuknya iaitu gas hidrogen dan gas oksigen menggunakan arus elektrik. Formula kimia bagi air ialah H₂O, yang menunjukkan setiap molekul air terbina daripada dua atom hidrogen dan satu atom oksigen. Persamaan tindak balas elektrolisis ialah: 2H₂O(cecair) → 2H₂(gas) + O₂(gas). Gas hidrogen (H₂) terbebas pada katod (elektrod negatif) manakala gas oksigen (O₂) terbebas pada anod (elektrod positif). Persamaan seimbang menunjukkan dua molekul hidrogen terhasil bagi setiap satu molekul oksigen. Pada suhu dan tekanan yang sama, nisbah isi padu kedua-dua gas juga 2 : 1, iaitu nisbah isi padu H₂ : O₂ = 2 : 1.</p><h5>✅ Mengapa jawapan B betul</h5><p>Nisbah isi padu hidrogen kepada oksigen ialah 2 : 1. Jika hidrogen ialah 20 cm³, maka isi padu oksigen di anod ialah 20 cm³ ÷ 2 = 10 cm³.</p><h5>❌ Mengapa pilihan lain salah</h5><ul><li><b>A</b> — 5 cm³ ialah satu perempat daripada 20 cm³, iaitu nisbah 4 : 1 yang tidak menepati nisbah isi padu gas H₂ : O₂ daripada persamaan seimbang.</li><li><b>C</b> — 20 cm³ menganggap nisbah 1 : 1, sedangkan nisbah pengeluaran gas hidrogen kepada gas oksigen ialah 2 : 1.</li><li><b>D</b> — 40 cm³ terbalik kerana mendarab dengan 2 dan bukannya membahagi isi padu gas hidrogen.</li></ul><h5>📌 Ingat</h5><p>Elektrolisis air menghasilkan gas Hidrogen di katod dan gas Oksigen di anod dengan nisbah isi padu Hidrogen : Oksigen = 2 : 1.</p>",
"<h5>🧠 Konsep utama</h5><p>Sifat kimia dan fizik sesuatu larutan boleh dikelaskan sebagai asid, neutral, atau alkali berdasarkan nilai pH dan tindak balas kimianya. Larutan asid mengandungi kepekatan ion hidrogen (H⁺) yang tinggi apabila larut dalam air. Ciri-ciri utama larutan asid merangkumi: berasa masam (seperti jus limau dan cuka), mengakis, bertindak balas dengan logam reaktif membebaskan gas hidrogen, mempunyai nilai pH kurang daripada 7 (pH < 7), serta menukarkan warna kertas litmus lembap daripada biru kepada merah. Sebaliknya, alkali mengandungi ion hidroksida (OH⁻), berasa pahit, licin apabila disentuh dengan jari, mempunyai pH lebih daripada 7, dan menukarkan litmus merah kepada biru.</p><h5>✅ Mengapa jawapan D betul</h5><p>Asid mempunyai rasa masam, nilai pH kurang daripada 7, dan menukarkan warna kertas litmus biru kepada merah.</p><h5>❌ Mengapa pilihan lain salah</h5><ul><li><b>A</b> — Rasa pahit, rasa licin, dan pH melebihi 7 ialah ciri-ciri khusus larutan alkali.</li><li><b>B</b> — Nilai pH melebihi 7 dan menukar litmus merah kepada biru ialah sifat alkali, bukan asid.</li><li><b>C</b> — Rasa pahit ialah sifat alkali, manakala pH 7 dan tidak mengubah warna litmus ialah sifat larutan neutral.</li></ul><h5>📌 Ingat</h5><p>Asid: rasa masam, pH < 7, litmus Biru → Merah. Alkali: rasa pahit/licin, pH > 7, litmus Merah → Biru.</p>",
"<h5>🧠 Konsep utama</h5><p>Kalium (K) ialah logam alkali Kumpulan 1 yang menduduki kedudukan paling atas dalam siri kereaktifan logam. Atom kalium mempunyai satu elektron valens yang sangat mudah dilepaskan untuk mencapai susunan elektron oktet yang stabil. Kereaktifan kalium sangat tinggi sehingga ia bertindak balas secara spontan dan cergas dengan gas oksigen serta wap air di udara atmosfera pada suhu bilik. Tindak balas kalium dengan air menghasilkan gas hidrogen dan haba; haba itu boleh menyalakan hidrogen. Tindak balasnya dengan oksigen pula menghasilkan sebatian oksida atau peroksida. Oleh itu, kalium perlu direndam sepenuhnya di dalam cecair lengai seperti minyak parafin untuk menghalang sentuhan langsung dengan oksigen dan kelembapan udara.</p><h5>✅ Mengapa jawapan A betul</h5><p>Minyak parafin bertindak sebagai lapisan pelindung yang menghalang kalium daripada bertindak balas dengan oksigen dan wap air di udara.</p><h5>❌ Mengapa pilihan lain salah</h5><ul><li><b>B</b> — Takat lebur kalium ialah sekitar 63 °C, jadi ia kekal sebagai pepejal lembut pada suhu bilik (bukan mudah melebur).</li><li><b>C</b> — Kalium ialah logam berketumpatan rendah (kurang tumpat daripada air) dan tergolong sebagai logam ringan, bukan sangat berat.</li><li><b>D</b> — Logam kalium biasa stabil secara nuklear dan tidak berubah menjadi bahan radioaktif apabila terdedah kepada udara.</li></ul><h5>📌 Ingat</h5><p>Logam alkali yang sangat reaktif (kalium, natrium, litium) mesti disimpan di dalam minyak parafin untuk mengelakkan tindak balas berbahaya dengan udara.</p>",
"<h5>🧠 Konsep utama</h5><p>Tindak balas kimia dikelaskan berdasarkan perubahan tenaga haba dengan persekitaran kepada dua kategori: eksotermik dan endotermik. Tindak balas eksotermik membebaskan tenaga haba ke persekitaran, menyebabkan suhu persekitaran meningkat. Tindak balas endotermik pula menyerap tenaga haba dari persekitaran, menyebabkan suhu persekitaran menurun. Semasa respirasi sel di dalam mitokondria, molekul glukosa dioksidakan oleh gas oksigen untuk menghasilkan karbon dioksida, air, dan membebaskan sejumlah besar tenaga: Glukosa + Oksigen → Karbon dioksida + Air + Tenaga. Sebahagian tenaga kimia disimpan dalam bentuk molekul ATP, manakala sebahagian lagi dibebaskan sebagai haba yang membantu memanaskan badan.</p><h5>✅ Mengapa jawapan D betul</h5><p>Respirasi sel membebaskan tenaga haba ke persekitaran, yang menepati takrifan proses eksotermik.</p><h5>❌ Mengapa pilihan lain salah</h5><ul><li><b>A</b> — Proses endotermik menyerap haba daripada persekitaran, sedangkan respirasi sel membebaskan haba.</li><li><b>B</b> — Fotosintesis memerlukan cahaya matahari, manakala respirasi sel berlaku berterusan tanpa memerlukan bantuan cahaya.</li><li><b>C</b> — Respirasi menggunakan oksigen dan menghasilkan karbon dioksida serta air, bukan menghasilkan gas oksigen.</li></ul><h5>📌 Ingat</h5><p>Eksotermik = haba keluar (dibebaskan), suhu naik (contoh: respirasi sel). Endotermik = haba daripada persekitaran diserap, seperti dalam tindak balas pek sejuk segera.</p>",
"<h5>🧠 Konsep utama</h5><p>Dalam litar elektrik bersiri, komponen disambungkan hujung ke hujung dalam satu laluan tunggal untuk pengaliran arus elektrik. Ciri-ciri litar bersiri adalah seperti berikut: 1. Arus yang mengalir melalui setiap komponen adalah sama besar (I = I₁ = I₂ = I₃). 2. Jumlah voltan atau beza keupayaan punca (bateri) dibahagikan merentasi semua komponen beban (V = V₁ + V₂ + V₃). Oleh sebab ketiga-tiga mentol adalah serupa, rintangan elektrik setiap mentol adalah sama. Berdasarkan Hukum Ohm (V = IR), beza keupayaan yang merentasi setiap mentol adalah sama nilainya, iaitu 2 V bagi setiap mentol. Jumlah beza keupayaan punca bateri = 2 V + 2 V + 2 V = 6 V.</p><h5>✅ Mengapa jawapan D betul</h5><p>Voltan bateri dalam litar bersiri ialah jumlah voltan ketiga-tiga mentol serupa: 2 V + 2 V + 2 V = 6 V (atau 3 × 2 V = 6 V).</p><h5>❌ Mengapa pilihan lain salah</h5><ul><li><b>A</b> — 0.67 V diperoleh jika voltan 2 V dibahagikan secara silap dengan tiga mentol.</li><li><b>B</b> — 2 V hanyalah voltan pada satu mentol, atau voltan bateri jika mentol disambung secara selari.</li><li><b>C</b> — 4 V hanya mengambil kira jumlah voltan bagi dua mentol sahaja (2 × 2 V = 4 V).</li></ul><h5>📌 Ingat</h5><p>Dalam litar bersiri, voltan bateri dibahagikan merentasi semua komponen (V_total = V₁ + V₂ + V₃), manakala arusnya sama di seluruh litar.</p>",
"<h5>🧠 Konsep utama</h5><p>Fenomena elektromagnetisme pertama kali dibuktikan oleh Hans Christian Oersted pada tahun 1820. Apabila arus elektrik mengalir melalui suatu konduktor (seperti dawai logam lurus), konduktor itu menjana medan magnet di ruang sekelilingnya. Corak garis medan magnet ini berbentuk bulatan sepusat mengelilingi dawai, dan arahnya boleh ditentukan menggunakan Petua Genggaman Tangan Kanan. Jarum kompas ialah magnet kecil yang bebas berputar dan sentiasa menjajarkan dirinya mengikut arah medan magnet setempat. Kehadiran medan magnet yang dihasilkan oleh arus elektrik dalam dawai mengenakan daya magnet pada jarum kompas, menyebabkan jarum kompas terpesong.</p><h5>✅ Mengapa jawapan B betul</h5><p>Pemesongan jarum kompas membuktikan bahawa pengaliran arus elektrik menghasilkan medan magnet di sekeliling dawai tersebut.</p><h5>❌ Mengapa pilihan lain salah</h5><ul><li><b>A</b> — Dawai biasanya diperbuat daripada kuprum yang merupakan bahan bukan magnet.</li><li><b>C</b> — Kompas ialah alat penunjuk arah magnetik dan tidak menjana sebarang arus elektrik dalam dawai.</li><li><b>D</b> — Daya graviti bumi tidak dipengaruhi dan tidak bertambah oleh pengaliran arus elektrik.</li></ul><h5>📌 Ingat</h5><p>Pengaliran arus elektrik sentiasa menjana medan magnet di sekeliling konduktor (prinsip asas elektromagnet).</p>",
"<h5>🧠 Konsep utama</h5><p>Kekenyalan ialah sifat bahan yang kembali ke bentuk asalnya selepas daya yang bertindak dialihkan. Menurut Hukum Hooke, pemanjangan spring (x) adalah berkadar terus dengan daya atau beban (F) yang dikenakan, selagi had kenyal tidak dilampaui. Panjang spring berbeban dikira sebagai: Jumlah panjang = Panjang asal + Pemanjangan. Berdasarkan jadual: Panjang asal spring apabila beban 0 N ialah 10 cm. Beban 1 N menghasilkan panjang 12 cm, iaitu pemanjangan = 12 − 10 = 2 cm bagi setiap 1 N beban. Bagi beban 5 N, pemanjangan spring = 5 N × 2 cm/N = 10 cm. Maka, jumlah panjang spring = 10 cm + 10 cm = 20 cm.</p><h5>✅ Mengapa jawapan C betul</h5><p>Pemanjangan spring untuk beban 5 N ialah 10 cm. Apabila ditambah kepada panjang asal 10 cm, jumlah panjang spring menjadi 20 cm.</p><h5>❌ Mengapa pilihan lain salah</h5><ul><li><b>A</b> — 10 cm ialah pemanjangan spring sahaja (atau panjang asal spring), bukan jumlah panjang spring berbeban.</li><li><b>B</b> — 18 cm ialah panjang spring apabila beban 4 N digantung padanya (10 cm + 4 × 2 cm = 18 cm).</li><li><b>D</b> — 25 cm boleh terhasil jika tersalah anggap pemanjangan ialah 3 cm bagi setiap 1 N: 10 cm + (5 × 3 cm) = 25 cm. Jadual menunjukkan kadar sebenar 2 cm bagi setiap 1 N.</li></ul><h5>📌 Ingat</h5><p>Perhatikan soalan: Jumlah panjang spring = panjang asal + pemanjangan. Jangan tersilap antara pemanjangan dengan jumlah panjang.</p>",
"<h5>🧠 Konsep utama</h5><p>Pemindahan haba berlaku melalui tiga cara, iaitu pengaliran, perolakan, dan sinaran. Kelalang termos direka khas untuk mengurangkan kehilangan haba melalui ketiga-tiga proses tersebut: 1. Ruang vakum di antara dua dinding kaca menghalang kehilangan haba secara pengaliran dan perolakan kerana tiada sebarang zarah jirim. 2. Penutup gabus atau plastik berpenebat menghalang kehilangan haba melalui perolakan udara dan pengaliran. 3. Sinaran haba inframerah masih boleh merambat merentasi ruang vakum. Oleh itu, dinding dalam kelalang disalut dengan lapisan perak yang berkilat dan licin. Permukaan berkilat merupakan pemantul sinaran haba yang sangat baik dan pemancar haba yang lemah, lalu memantulkan semula sinaran haba ke dalam cecair.</p><h5>✅ Mengapa jawapan B betul</h5><p>Lapisan perak yang berkilat berfungsi memantulkan semula sinaran haba ke dalam cecair panas bagi meminimumkan kehilangan haba secara sinaran.</p><h5>❌ Mengapa pilihan lain salah</h5><ul><li><b>A</b> — Kehilangan haba melalui pengaliran dihalang oleh ruang vakum dan bahan penebat termos, bukan oleh lapisan berkilat.</li><li><b>C</b> — Kehilangan haba melalui perolakan dihalang oleh ruang vakum dan penutup kelalang yang kedap.</li><li><b>D</b> — Kelalang termos ialah bekas pasif yang mengekalkan suhu dan tidak membekalkan tenaga haba baharu kepada cecair.</li></ul><h5>📌 Ingat</h5><p>Ciri kelalang termos: Ruang vakum menghalang pengaliran dan perolakan; permukaan perak berkilat memantulkan sinaran haba.</p>",
"<h5>🧠 Konsep utama</h5><p>Warna primer cahaya terdiri daripada warna Merah, Hijau, dan Biru. Warna primer tidak boleh dihasilkan melalui percampuran cahaya warna lain. Prinsip penambahan warna cahaya menyatakan bahawa apabila dua warna primer cahaya disinari bertindih pada skrin putih, warna sekunder akan terhasil: 1. Cahaya Merah + Cahaya Hijau = Cahaya Kuning. 2. Cahaya Hijau + Cahaya Biru = Cahaya Sian. 3. Cahaya Merah + Cahaya Biru = Cahaya Magenta. Apabila ketiga-tiga warna primer (Merah, Hijau, dan Biru) disinari serentak dengan keamatan yang sama, kawasan pertindihan akan menghasilkan cahaya putih.</p><h5>✅ Mengapa jawapan A betul</h5><p>Penambahan dua warna primer cahaya iaitu merah dan hijau pada kawasan bertindih menghasilkan warna sekunder kuning.</p><h5>❌ Mengapa pilihan lain salah</h5><ul><li><b>B</b> — Sian ialah warna sekunder yang terhasil daripada penambahan cahaya hijau dan cahaya biru.</li><li><b>C</b> — Magenta ialah warna sekunder yang terhasil daripada percampuran cahaya merah dan cahaya biru.</li><li><b>D</b> — Cahaya putih hanya terhasil apabila ketiga-tiga warna primer iaitu merah, hijau, dan biru bertindih serentak.</li></ul><h5>📌 Ingat</h5><p>Penambahan warna primer cahaya: Merah + Hijau = Kuning; Hijau + Biru = Sian; Merah + Biru = Magenta; Merah + Hijau + Biru = Putih.</p>",
"<h5>🧠 Konsep utama</h5><p>Bunyi dikelaskan mengikut frekuensi kepada infrasonik (kurang daripada 20 Hz), bunyi boleh dengar manusia (20 Hz hingga 20 000 Hz), dan ultrasonik (melebihi 20 000 Hz). Kelawar ialah mamalia yang aktif pada waktu malam. Selain menggunakan penglihatan, kelawar menggunakan ekolokasi untuk mengesan halangan dan mangsa dalam gelap. Kelawar memancarkan denyutan gelombang bunyi ultrasonik berfrekuensi tinggi melalui mulut atau hidungnya. Apabila gelombang ini mengenai sasaran seperti serangga atau halangan fizikal, gelombang tersebut dipantulkan kembali sebagai gema. Telinga kelawar yang sangat peka mengesan masa penerimaan dan arah gema pantulan tersebut untuk menentukan kedudukan, jarak, dan saiz mangsa secara tepat.</p><h5>✅ Mengapa jawapan D betul</h5><p>Kelawar menghasilkan gelombang bunyi ultrasonik dan mentafsir gema pantulannya daripada mangsa untuk terbang dan memburu dalam gelap secara ekolokasi.</p><h5>❌ Mengapa pilihan lain salah</h5><ul><li><b>A</b> — Kelawar tidak mempunyai organ biopendarcahaya dan tidak menghasilkan cahaya dari badannya.</li><li><b>B</b> — Kelawar tidak menggunakan organ pengesan haba inframerah; organ lubang deria haba dimiliki oleh ular seperti ular kapak.</li><li><b>C</b> — Gelombang ultrasonik (> 20 000 Hz) yang digunakan oleh kelawar, bukannya gelombang infrasonik (< 20 Hz).</li></ul><h5>📌 Ingat</h5><p>Ekolokasi pada kelawar memanfaatkan gelombang bunyi ultrasonik berfrekuensi tinggi (> 20 000 Hz) dan pantulan gemanya.</p>",
"<h5>🧠 Konsep utama</h5><p>Penggunaan tenaga elektrik disukat dalam unit kilowatt-jam (kWj), di mana 1 kWj bersamaan dengan penggunaan tenaga 1 kilowatt selama 1 jam. Rumus pengiraan tenaga elektrik yang digunakan ialah: Tenaga elektrik (kWj) = Kuasa (kW) × Masa (jam). Langkah pengiraan: 1. Kuasa penyaman udara = 1.5 kW. 2. Jumlah masa penggunaan dalam 30 hari = 8 jam/hari × 30 hari = 240 jam. 3. Jumlah tenaga yang digunakan = 1.5 kW × 240 jam = 360 kWj. 4. Kos penggunaan = Jumlah tenaga (kWj) × Kadar tarif = 360 kWj × RM0.50/kWj = RM180.</p><h5>✅ Mengapa jawapan C betul</h5><p>Jumlah tenaga yang digunakan selama 30 hari ialah 360 kWj. Pada kadar tarif 50 sen (RM0.50) setiap kWj, kos elektrik ialah RM180.</p><h5>❌ Mengapa pilihan lain salah</h5><ul><li><b>A</b> — RM6 ialah kos penggunaan penyaman udara untuk tempoh satu hari sahaja (1.5 kW × 8 jam × RM0.50 = RM6).</li><li><b>B</b> — RM60 diperoleh jika tersalah kira penggunaan selama 10 hari sahaja: 1.5 kW × 8 jam × 10 hari × RM0.50/kWj = RM60.</li><li><b>D</b> — RM360 diperoleh jika 360 kWj disalah darab dengan RM1 bagi setiap kWj. Kadar sebenar ialah RM0.50 bagi setiap kWj, jadi kosnya RM180.</li></ul><h5>📌 Ingat</h5><p>Kos elektrik = Kuasa (kW) × Masa (jam) × Tarif seunit. Pastikan kuasa dinyatakan dalam kW dan masa dalam jam.</p>",
"<h5>🧠 Konsep utama</h5><p>Sinaran mengion seperti sinar-X dan sinar gama mempunyai tenaga yang tinggi dan boleh mengionkan atom dalam sel badan, merosakkan DNA, serta berisiko menyebabkan mutasi atau kanser jika pendedahan berlebihan berlaku. Pekerja di jabatan radiologi terdedah kepada risiko sinaran semasa mengendalikan mesin pengimejan. Oleh itu, mereka diwajibkan memakai lencana dosimeter filem pada pakaian seragam mereka. Lencana ini mengandungi kepingan filem fotografi yang terlindung daripada cahaya biasa tetapi sensitif terhadap sinaran mengion. Apabila sinaran menembusi lencana, filem akan menjadi hitam selepas diproses. Tahap kehitaman filem diukur untuk menentukan jumlah dos sinaran kumulatif yang telah diserap oleh pekerja bagi memastikan ia kekal pada tahap selamat.</p><h5>✅ Mengapa jawapan B betul</h5><p>Lencana filem berfungsi sebagai alat dosimeter untuk mengesan dan merekodkan dos sinaran kumulatif yang diterima oleh pekerja.</p><h5>❌ Mengapa pilihan lain salah</h5><ul><li><b>A</b> — Lencana filem tidak memberi perlindungan sinaran; perlindungan badan dicapai dengan memakai apron berplumbum.</li><li><b>C</b> — Lencana filem ialah alat pengesan pasif dan tidak menghasilkan sebarang sinaran.</li><li><b>D</b> — Lencana dosimeter bukan sekadar kad identiti atau tag jawatan, tetapi alat keselamatan radiasi berteknologi khas.</li></ul><h5>📌 Ingat</h5><p>Lencana filem (dosimeter) mengukur dan merekodkan dos sinaran yang diterima pekerja; ia bukan pelindung daripada sinaran.</p>",
"<h5>🧠 Konsep utama</h5><p>Fotosfera ialah lapisan permukaan atmosfera Matahari yang memancarkan cahaya kelihatan yang kita lihat dari Bumi, dengan suhu purata sekitar 5 500 °C hingga 6 000 °C. Tompok matahari merupakan tompokan atau fenomena sementara yang terbentuk pada fotosfera Matahari. Kawasan tompok matahari mempunyai aktiviti medan magnet yang teramat kuat, yang bertindak merencat dan memperlahankan arus perolakan gas plasma panas dari bahagian dalam Matahari ke permukaan. Akibatnya, kawasan ini mempunyai suhu yang lebih rendah, iaitu sekitar 3 500 °C hingga 4 000 °C berbanding kawasan sekitarnya. Kawasan yang lebih sejuk ini memancarkan kurang cahaya kelihatan dan kelihatan gelap secara kontras dengan permukaan fotosfera yang sangat terang.</p><h5>✅ Mengapa jawapan B betul</h5><p>Tompok matahari kelihatan lebih gelap kerana suhunya jauh lebih rendah berbanding kawasan fotosfera di sekelilingnya akibat kepekatan medan magnet yang kuat.</p><h5>❌ Mengapa pilihan lain salah</h5><ul><li><b>A</b> — Matahari ialah jasad gas plasma tanpa permukaan pepejal, jadi tompok matahari bukan lubang fizikal.</li><li><b>C</b> — Tompok matahari ialah struktur sebenar pada fotosfera Matahari, bukannya bayang-bayang daripada planet yang melintas.</li><li><b>D</b> — Suhu permukaan Matahari yang mencecah ribuan darjah Celsius tidak membenarkan pembentukan awan wap air.</li></ul><h5>📌 Ingat</h5><p>Tompok matahari kelihatan gelap secara kontras kerana suhunya lebih sejuk (~4 000 °C) berbanding fotosfera sekitarnya (~6 000 °C).</p>",
"<h5>🧠 Konsep utama</h5><p>Galaksi ialah sistem gergasi yang terdiri daripada berbilion-bilion bintang, debu kosmik, gas antara bintang, dan jirim gelap yang terikat bersama oleh daya tarikan graviti. Berdasarkan morfologi, galaksi dikelaskan kepada tiga bentuk utama: galaksi berpilin (lingkaran), galaksi elips, dan galaksi tidak sekata. Sistem Suria kita, yang merangkumi Matahari, planet Bumi, dan ahli-ahli sistem suria yang lain, terletak di dalam sebuah galaksi berpilin berpalang yang dinamakan Galaksi Bima Sakti (Milky Way). Kedudukan Sistem Suria kita berada pada salah satu cabang pilin luar Bima Sakti yang dikenali sebagai Lengan Orion, kira-kira 26 000 tahun cahaya dari pusat galaksi.</p><h5>✅ Mengapa jawapan D betul</h5><p>Sistem Suria kita terletak di dalam sebuah galaksi berpilin yang dikenali sebagai Bima Sakti (Milky Way).</p><h5>❌ Mengapa pilihan lain salah</h5><ul><li><b>A</b> — Andromeda ialah galaksi berpilin jiran terdekat kepada Bima Sakti dalam Kumpulan Tempatan, bukan galaksi kita.</li><li><b>B</b> — Magellan Besar ialah galaksi kerdil yang mengorbit di luar galaksi Bima Sakti.</li><li><b>C</b> — Triangulum ialah galaksi berpilin jiran yang berasingan dalam Kumpulan Tempatan galaksi.</li></ul><h5>📌 Ingat</h5><p>Sistem Suria kita berada di dalam Galaksi Bima Sakti (Milky Way), iaitu sebuah galaksi jenis berpilin.</p>",
"<h5>🧠 Konsep utama</h5><p>Pergerakan dan pecutan roket di angkasa lepas dijelaskan oleh Hukum Gerakan Newton Ketiga dan prinsip keabadian momentum. Hukum Gerakan Newton Ketiga menyatakan bahawa bagi setiap daya tindakan, sentiasa wujud daya tindak balas yang sama magnitud tetapi bertindak pada arah yang bertentangan. Di dalam enjin roket, pembakaran bahan api dan pengoksida menghasilkan gas panas bertekanan tinggi yang dipancutkan keluar dengan kelajuan teramat tinggi ke arah belakang melalui muncung roket (daya tindakan). Secara serentak, gas ekzos tersebut mengenakan daya tolakan ke hadapan (daya tujah) yang sama besar ke atas badan roket (daya tindak balas). Daya tujah ini tidak memerlukan kehadiran udara atmosfera di sekelilingnya untuk menolak roket memecut ke hadapan.</p><h5>✅ Mengapa jawapan B betul</h5><p>Roket memecut mengikut Hukum Gerakan Newton Ketiga di mana gas ekzos ditolak ke belakang dan gas tersebut menolak roket ke hadapan dengan daya yang sama besar.</p><h5>❌ Mengapa pilihan lain salah</h5><ul><li><b>A</b> — Tarikan graviti masih wujud di angkasa lepas; tarikan graviti bumi dan matahari mengekalkan objek dalam orbit.</li><li><b>C</b> — Tarikan graviti Bulan tidak membekalkan daya tujah utama untuk pecutan kapal angkasa; pecutan dijana oleh enjin roket sendiri.</li><li><b>D</b> — Udara di dalam kabin roket menolak dinding ke semua arah secara seimbang dan tidak menghasilkan daya tujah bersih ke hadapan.</li></ul><h5>📌 Ingat</h5><p>Roket bergerak berdasarkan Hukum Newton Ketiga: Tindakan memancutkan gas ekzos ke belakang menghasilkan tindak balas daya tujah roket ke hadapan.</p>"]};
